    subroutine read_calibration_state()

        ! The other half of the resume. Absent file means a fresh start, which is
        ! what a first run wants, so this is silent rather than an error. Delete
        ! calibration_state.dat to force one.

        use Global_Vars

        implicit none

        logical :: state_exists_1
        character(len=40) :: state_tag_1
        integer :: state_ios_1

        inquire(file="calibration_state.dat",exist=state_exists_1)

        if (.NOT. state_exists_1) then

            write(*,*) "no calibration_state.dat, starting from the declared values"

            return

        end if

        open(unit=72,file="calibration_state.dat",action='read')

            read(72,'(A)') state_tag_1

            if (trim(state_tag_1) .NE. "calibration_state_v3") then

                write(*,*) "calibration_state.dat is not version 3, ignoring it"
                close(72)

                return

            end if

            read(72,'(F30.15)') discount_factor
            read(72,'(F30.15)') discount_factor_on_child
            read(72,'(F30.15)') minimum_inheritance
            read(72,'(F30.15)') advantage_to_owning
            read(72,'(F30.15)') relative_share_of_housing
            read(72,'(F30.15)') relative_share_of_leisure
            read(72,'(F30.15)') largest_house_size
            read(72,'(F30.15)') smallest_rental_relative_to_lowest_income
            read(72,'(F30.15)') labor_income_tax_rate
            read(72,'(F30.15)') standard_deduction_as_percent_of_average_labor_income
            read(72,'(F30.15)') probability_of_becoming_addicted_if_experiment
            read(72,'(F30.15)') lambda_addiction
            read(72,'(F30.15)') price_of_addictive_good
            read(72,'(F30.15)') drug_supply_shifter
            read(72,'(F30.15)') utility_cost_of_treatment
            read(72,'(F30.15)') previous_utility_cost_of_treatment
            read(72,'(F30.15)') previous_treatment_take_up
            read(72,'(I10)') have_treatment_secant
            read(72,'(F30.15)') previous_onset_at_mean
            read(72,'(F30.15)') previous_sud_rate
            read(72,'(I10)') have_lambda_secant
            read(72,'(F30.15)') size_homelessness
            read(72,'(F30.15)') fixed_cost_to_moving
            read(72,'(F30.15)') housing_status_grid_expander
            read(72,'(F30.15)') smallest_house_size_adjuster
            read(72,'(F30.15)') largest_house_size_adjuster
            read(72,'(F30.15)') previous_gap_smallest_house_size
            read(72,'(F30.15)') previous_gap_largest_house_size
            read(72,'(I10)') have_gap_smallest_house_size
            read(72,'(I10)') have_gap_largest_house_size
            read(72,'(I10)') resumed_loop_count
            read(72,'(F30.15)') housing_price(1)
            read(72,'(F30.15)') rent(1,:)
            read(72,'(F30.15)') convexity_of_rental_company
            read(72,'(F30.15)') inheritance_amount
            read(72,'(F30.15)') lambda_m
            read(72,'(F30.15)') kappa_uem
            read(72,'(F30.15)') rho_m
            read(72,'(F30.15)') rho_d
            read(72,'(F30.15)') addiction_scalar_1
            read(72,'(F30.15)') addiction_scalar_adjuster
            read(72,'(F30.15)') previous_gap_addiction_scalar
            read(72,'(I10)') have_gap_addiction_scalar
            read(72,'(F30.15)') max_food_cost
            read(72,'(F30.15)') mu_homeless
            read(72,'(F30.15)') penalty_child_addicted
            read(72,'(F30.15)') penalty_child_addicted_adjuster
            read(72,'(F30.15)') previous_gap_penalty_child
            read(72,'(I10)') have_gap_penalty_child
            read(72,'(F30.15)') probability_becoming_unemployed
            read(72,'(F30.15)') probability_of_voucher_benchmark_used
            read(72,'(F30.15)') relative_share_of_addiction_1
            read(72,'(F30.15)') sd_permanent_productivity
            read(72,'(F30.15)') value_of_life
            read(72,'(F30.15)') value_of_life_at_bracket
            read(72,'(F30.15)') weight_on_child
            read(72,'(F30.15)') multiple_of_probabilities_of_employment_if_addicted
            read(72,'(F30.15)') discount_factor_adjuster
            read(72,'(F30.15)') discount_factor_lo
            read(72,'(F30.15)') discount_factor_hi
            read(72,'(F30.15)') discount_factor_lo_moment
            read(72,'(F30.15)') discount_factor_hi_moment
            read(72,'(F30.15)') previous_gap_discount_factor
            read(72,'(I10)') have_gap_discount_factor
            read(72,'(F30.15)') size_homelessness_lo
            read(72,'(F30.15)') size_homelessness_hi
            read(72,'(F30.15)') size_homelessness_lo_moment
            read(72,'(F30.15)') size_homelessness_hi_moment

            ! READ TOLERANTLY FROM HERE ON, so a state file written before these
            ! fields existed still resumes instead of being thrown away. A short
            ! file leaves them at their declared values, which is what a fresh
            ! start would use anyway, and the alternative is a version bump that
            ! discards every loop already paid for.
            read(72,'(F30.15)',iostat=state_ios_1) value_of_life_trust

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_value_of_life

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_value_of_life

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) size_homelessness_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_size_homelessness

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_size_homelessness

            end if


            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) voucher_probability_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_voucher_probability

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_voucher_probability

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) separation_rate_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_separation_rate

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_separation_rate

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) employment_multiplier_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_employment_multiplier

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_employment_multiplier

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) relative_share_of_housing_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_relative_share_of_housing

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_relative_share_of_housing

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) labor_income_tax_rate_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_labor_income_tax_rate

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_labor_income_tax_rate

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) lambda_clamp

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_lambda_addiction

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_lambda_addiction

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) relative_share_of_leisure_adjuster

            end if

            if (state_ios_1==0) then

                read(72,'(F30.15)',iostat=state_ios_1) previous_gap_relative_share_of_leisure

            end if

            if (state_ios_1==0) then

                read(72,'(I10)',iostat=state_ios_1) have_gap_relative_share_of_leisure

            end if

            if (state_ios_1/=0) then

                write(*,*) "calibration_state.dat predates some damping state; anything missing",&
                    " starts from its declared value. The trust region",&
                    " starts at", value_of_life_trust_start, " and the homelessness adjuster at",&
                    size_homelessness_adjuster_start
                value_of_life_trust=value_of_life_trust_start
                previous_gap_value_of_life=0
                have_gap_value_of_life=0
                size_homelessness_adjuster=size_homelessness_adjuster_start
                previous_gap_size_homelessness=0
                have_gap_size_homelessness=0

            end if

        close(72)

        write(*,*) "resumed from calibration_state.dat, written after loop", resumed_loop_count
        write(*,*) "lambda_addiction=", lambda_addiction
        write(*,*) "largest_house_size=", largest_house_size
        write(*,*) "smallest_rental_relative_to_lowest_income=", smallest_rental_relative_to_lowest_income
        write(*,*) "lambda_m=", lambda_m
        write(*,*) "kappa_uem=", kappa_uem
        write(*,*) "rho_m=", rho_m
        write(*,*) "rho_d=", rho_d

    end subroutine

    subroutine write_calibration_distribution()

    ! THE DISTRIBUTION IS THE OTHER HALF OF A WARM START, and it is the
    ! expensive half.
    !
    ! A resumed run that recovers the parameters still pays 655 sweeps to
    ! rebuild the distribution from the age one cross section, and those
    ! sweeps are most of a loop. The converged distribution of the last
    ! completed loop is a far better guess for the next parameter vector than
    ! a freshly initialised one, because consecutive vectors differ by a
    ! damped step.
    !
    ! Written on the same schedule as the parameters and to a temporary first,
    ! for the same reason. It is a large file, so it is written once per loop
    ! and not once per sweep.

    use Global_Vars

    implicit none

    integer :: dist_index_1
    character*1 :: string_used_1

    do dist_index_1=1,2

        write(string_used_1,'(i1)') dist_index_1

        open(unit=73,file="calibration_distribution"//trim(string_used_1)//".tmp",&
            action='write',status='replace')
            write(73,'(F30.28)') distribution_stationary(dist_index_1)%vector_transition_real(1,:,:,:,:,:,:)
        close(73)

        call rename("calibration_distribution"//trim(string_used_1)//".tmp",&
            "calibration_distribution"//trim(string_used_1)//".dat")

    end do

    end subroutine

    subroutine read_calibration_distribution()

    ! Loads the warm start if it is there, and records that it did, because the
    ! caller has to skip initialize_feasible_distribution when it did. Both
    ! files have to be present: half a warm start is two distributions from
    ! different loops, which is not a distribution of anything.

    use Global_Vars

    implicit none

    integer :: dist_index_1
    logical :: exists_1,exists_2
    character*1 :: string_used_1

    have_warm_distribution=0

    inquire(file="calibration_distribution1.dat",exist=exists_1)
    inquire(file="calibration_distribution2.dat",exist=exists_2)

    if (.NOT. (exists_1 .AND. exists_2)) then

        write(*,*) "no warm start distribution, initialising from the age one cross section"

        return

    end if

    do dist_index_1=1,2

        write(string_used_1,'(i1)') dist_index_1

        open(unit=74,file="calibration_distribution"//trim(string_used_1)//".dat",action='read')
            read(74,'(F30.28)') distribution_stationary(dist_index_1)%vector_transition_real(1,:,:,:,:,:,:)
        close(74)

        distribution_guess(dist_index_1)%vector_transition_real(1,:,:,:,:,:,:)=&
            distribution_stationary(dist_index_1)%vector_transition_real(1,:,:,:,:,:,:)

    end do

    have_warm_distribution=1

    write(*,*) "warm start distribution loaded, sum=", &
        sum(distribution_guess(1)%vector_transition_real(1,:,:,:,:,:,:))+&
        sum(distribution_guess(2)%vector_transition_real(1,:,:,:,:,:,:))

    end subroutine

    subroutine calibrating_model()
    
        use Global_Vars
        
        implicit none
        
        logical :: file_exists
        
        real(8) :: mass_at_top_financial,a,b,c,d
        real(8) :: mean_drug_quantity_1,onset_at_mean_1,onset_step_1,treatment_step_1
        character*1 :: string_used
        integer :: last_period_of_life,addiction_index
        integer, dimension(1) :: index_drug_1
                                
        simulation_ended=0

        ! Pick up where a killed run left off, if it left anything.
        call read_calibration_state()

        ! THE SMOOTH HAZARD NEEDS THE TABULATED EXPECTATION. With the hoist off
        ! the two continuations are never formed separately, so there is nothing
        ! to price the drug risk against and the household would face a hazard
        ! rising in v that it does not respond to, which is the defect this was
        ! meant to fix wearing a different hat. Stop rather than run: a model
        ! that still produces numbers is exactly how this would go unnoticed.
        if ((smooth_addiction_hazard==1) .AND. (hoist_expectation==0)) then

            write(*,*) "smooth_addiction_hazard needs hoist_expectation=1. stopping."
            stop

        end if

        call cpu_time(simulation_start_time)
        
        lump_sum_transfer(1)=0
        
        model_average_owner_occupied_unit_size(1)=calibrated_stationary_housing_price*&
            average_owner_occupied_house_size_calibrated
            
        model_average_rental_unit_size(1)=0.116

        loop_count=0  
        
        model_bequests(1)=2.5238247842094039
        
        model_drug_threshold(1)=drug_threshold_guess
        model_average_income(1)=average_labor_income_calibrated
        model_average_income_plus_assets(1)=average_labor_income_calibrated
        model_average_income_plus_all_assets(1)=average_labor_income_calibrated
        model_average_labour_income(1)=average_labor_income_calibrated
        model_average_labour_income_by_employment(1,:)=average_labor_income_by_employment_calibrated
        median_income(1)=median_income_calibrated
        model_average_financial(1)=average_financial_calibrated
        model_average_net_wealth(1)=average_net_wealth_calibrated
        
        call allocate_matrix()
        
        call initialize_variables_and_grids()
        call GKKOC_intergenerational_employment_process(1)
        call initialize_financial_grid(1)
                
        call initialize_feasible_distribution(1)
            
        if (use_old_results==1) then
        
            call upload_vars(1)
            
        else
        
            housing_price(1)=calibrated_stationary_housing_price
                    
            if (fix_rent==0) then
                rent(1,:)=rent_to_housing_price*housing_price(1)*1.05
            else
                ! FIXED RENT STILL HAS TO BE SET. rent has no initialiser, so
                ! guarding the assignments that would move it also removed the
                ! one that gave it a value, and it ran on whatever was in memory.
                rent(1,:)=rent_calibrated(:)
            end if
                                          
            risk_free_rate(1)=calibrated_risk_free_rate
            mortgage_interest_rate(1)=risk_free_rate(1)+mortgage_interest_gap
            
            model_average_labour_income(1)=average_labor_income_calibrated
            total_housing_demand(1)=calibrated_housing_stock
            
            total_rental_demand(1,:)=total_rental_supply_calibrated
            total_rental_supply(1,:)=total_rental_supply_calibrated
            
        end if
                
        call function_of_utility_advantage_from_homeowning(1)
                                               
        call set_SS_benefits(1)
        
        call function_of_utility_advantage_from_homeowning(1)
        call initialize_financial_grid(1)
                
        distance_value_function=1
        distance_lambda_m=1
        distance_kappa_uem=1
        distance_rho_m=1
        distance_rho_d=1
        distance_discount_factor=1

        ! The convexity of the rental company is not calibrated, its adjuster is
        ! zero, and its distance was assigned in exactly one place: the branch
        ! taken when the parameters are held fixed. On the calibrating path it
        ! was never written at all, so the loop condition was testing
        ! uninitialised memory against 1e-3 and the sweep could not terminate.
        distance_convexity_of_rental_company=0

        distance_discount_factor_on_child=1
        distance_minimum_inheritance=1
        distance_advantage_to_owning=1
        distance_relative_share_of_housing=1
        distance_relative_share_of_leisure=1
        distance_standard_deduction=1
        distance_housing_status_grid_expander=1
        distance_largest_house_size=1
