        write(*,*) "rent=",rent(1,:)
        write(*,*) "lump_sum_transfer=", lump_sum_transfer(1)
        write(*,*) "minimum_downpayment=", minimum_downpayment
        write(*,*) "max_amortization_years=", max_amortization_years
