        write(*,*) "c_1=", c_1
        write(*,*) "c_min=", c_min
        write(*,*) "cutoff_housing_investment=", cutoff_housing_investment
        write(*,*) "infinite_elasticity_of_rental_supply=", infinite_elasticity_of_rental_supply
        write(*,*) "calibration"
        write(*,*) "advantage_to_owning=", advantage_to_owning
        write(*,*) "unconditional_employment_probability=", unconditional_employment_probability
                
        if (use_old_results==0) then
                    
            if (fix_rent==0) then
                rent(1,:)=housing_price(1)*himmelberg_etal_rent_to_price
            else
                rent(1,:)=rent_calibrated(:)
            end if
            
        end if
        
        ! TRACKS THE RENT rather than repeating its value. Hardcoded, this
        ! silently kept the old level after p_r was renormalised.
        model_average_rent(1)=rent(1,0)
        
        call set_smallest_house_size()
        
        call function_of_utility_advantage_from_homeowning(1)
                 
        write(*,*) "rent=", rent(1,:)
                  
        write(*,*) "property_tax=", property_tax
        write(*,*) "max_debt_to_income_ratio=", max_debt_to_income_ratio
        write(*,*) "max_debt_to_income_ratio_below_80=", max_debt_to_income_ratio_below_80
        write(*,*) "smallest_house_size=", smallest_house_size
        write(*,*) "housing_size(smallest_house_to_buy)=", housing_size(index_of_smallest_house_hhld_can_buy)
        write(*,*) "lowest_housing_grid_point=", lowest_housing_grid_point
        write(*,*) "employment_grid=", employment_grid(1,:)
        write(*,*) "value_of_initial_assets=", value_of_initial_assets
        write(*,*) "initial_endowment=", initial_endowment      
        write(*,*) "standard_deduction=", standard_deduction
        write(*,*) "personal_exemption=", personal_exemption
        write(*,*) "model_average_labour_income=", model_average_labour_income(1)
        write(*,*) "average_labor_income_calibrated=", average_labor_income_calibrated
        write(*,*) "weight_on_labor_income=", weight_on_labor_income
        write(*,*) "inheritance_amount=", inheritance_amount
        write(*,*) "relative_share_of_leisure=", relative_share_of_leisure
        
        INQUIRE(FILE="total_rental_demand"//trim(long_run_simulation)//".dat", EXIST=file_exists)
                
!        if ((re_calibrate_management_costs==1) .AND. (zero_elasticity==0) .AND. &
!            (infinite_elasticity_of_rental_supply==0) .AND. (file_exists)) then
!        
!            open(unit=39,file="total_rental_demand"//trim(long_run_simulation)//".dat",action='read')
!                read(39,'(F15.12)') total_rental_demand(1,:)
!            close(39)
!            
!            do j=0,have_two_rental_markets
!                        
!                call solve_elasticity_of_rental_housing(1,convexity_of_rental_company(j),j)
!                        
!                rental_management_costs=&
!                    (rent(1,j)-housing_price(1)*&
!                    (risk_free_rate(1)+housing_depreciation_rate+property_tax(1)+&
!                    property_tax_on_rental_housing)/(1+risk_free_rate(1)))/&
!                    ((total_rental_demand_segmented(1,j)**&
!                    (convexity_of_rental_company(j)-1))*convexity_of_rental_company(j))
!                    
!            end do
!        
!            open(unit=27,file="rental_management_costs"//trim(file_number)//".dat",status='replace')
!                write(27,'(F30.29)') rental_management_costs
!            close(27)
!            
!            open(unit=27,file="convexity_of_rental_company"//trim(file_number)//".dat",status='replace')
!                write(27,'(F15.12)') convexity_of_rental_company
!            close(27)
!                                    
!        end if
        
        write(*,*) "rental_management_costs=", rental_management_costs
        write(*,*) "file_number=", file_number
        write(*,*) "fraction_to_repay=", fraction_to_repay         
        write(*,*) "prepayment_penalty_starts_from=", prepayment_penalty_starts_from
        write(*,*) "file_number=", file_number
        write(*,*) "empirical_housing_supplpy_elasticity=", empirical_housing_supplpy_elasticity
        write(*,*) "replacement_rate_ui=", replacement_rate_ui
        write(*,*) "size_homelessness=", size_homelessness
        write(*,*) "model_average_financial=", model_average_financial(1)
        write(*,*) "model_average_net_wealth=", model_average_net_wealth(1)
        write(*,*) "relative_share_of_addiction=", relative_share_of_addiction_2
        write(*,*) "relative_share_of_consumption_2=", relative_share_of_consumption_2
        write(*,*) "relative_share_of_housing_2=", relative_share_of_housing_2
        write(*,*) "relative_share_of_addiction_2=", relative_share_of_addiction_1
        write(*,*) "relative_share_of_consumption_1=", relative_share_of_consumption_1
        write(*,*) "relative_share_of_housing_1=", relative_share_of_housing_1
        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1
        write(*,*) "sum 2=", relative_share_of_consumption_2+relative_share_of_housing_2+relative_share_of_addiction_2
        write(*,*) "sum 1=", relative_share_of_consumption_1+relative_share_of_housing_1+relative_share_of_addiction_1
        write(*,*) "model_ss_benefits=", model_ss_benefits
        write(*,*) "price_of_addictive_good=", price_of_addictive_good
        write(*,*) "hello1"
        write(*,*) "expected_age_non_addicted=", expected_age_non_addicted+25
        write(*,*) "expected_age_homeless=", expected_age_homeless+25
        write(*,*) "expected_age_addicted=", expected_age_addicted+25
        write(*,*) "expected_age_homeless_and_addicted=", expected_age_homeless_and_addicted+25
                
        previous_average_labor_income=model_average_labour_income(1)
        previous_median_income=median_income(1)
        previous_average_net_wealth=model_average_net_wealth(1)
        previous_inheritance_amount=inheritance_amount
        
        write(*,*) "adjusted_probability=", adjusted_probability(:)
        write(*,*) "probability_of_voucher=", probability_of_voucher
        write(*,*) "addiction_scalar_1=", addiction_scalar_1
        
        do i=1,employment_grid_size
            write(*,*) "employment_grid(",i,")=", employment_grid(1,i)
        end do
        
        do i=1,employment_grid_size
            write(*,*) "employment_grid(",i,")=", employment_grid(30,i)
        end do
        
        write(*,*) "increased_risk_of_death_addicted=", increased_risk_of_death_addicted
        write(*,*) "multiple_of_probabilities_of_employment_if_addicted=", multiple_of_probabilities_of_employment_if_addicted
        write(*,*) "relative_share_of_addiction_2=", relative_share_of_addiction_2
        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1
        write(*,*) "size_of_penalty=", size_of_penalty
        write(*,*) "voucher_probabilities=", voucher_probabilities(0,1,1,:)
        write(*,*) "voucher_probabilities=", voucher_probabilities(1,1,1,:)
        write(*,*) "voucher_probabilities_benchmark=", voucher_probabilities_benchmark(0,1,1,:)
        write(*,*) "voucher_probabilities_benchmark=", voucher_probabilities_benchmark(1,1,1,:)
        
        write(*,*) "increased_risk_of_death_addicted*(1-sum(actual_survival_probability)/life_span)=", &
            increased_risk_of_death_addicted*(1-sum(actual_survival_probability)/life_span)
            
        do i=1,bins_drug_spending_relative_to_average
        
            drug_spending_relative_to_average(i)=(i-1)/(real(bins_drug_spending_relative_to_average)/real(100))
        
        end do
        
        index_drug_1(1)=min(max(minloc(drug_spending_relative_to_average(:)-0.5,1,&
            mask=drug_spending_relative_to_average(:)-0.5>0),1),&
            bins_drug_spending_relative_to_average) 

        ! THE WARM START IS READ HERE AND NOT WITH THE PARAMETERS, because it
        ! writes into distribution_stationary and distribution_guess and those do
        ! not exist until allocate_matrix has run. Reading it beside
        ! read_calibration_state, which only moves scalars, wrote into unallocated
        ! derived type components and segfaulted before the first line of output.
        ! The symptom was a binary that had just run fine crashing on startup, and
        ! the only thing that had changed was that a previous loop had left a
        ! checkpoint on disk for it to read.
        call read_calibration_distribution()
                                    
        do while((distance_rental_market(1)>stopping_rule_rental_market) .OR. &
            (distance_discount_factor>stopping_rule_discount_factor) .OR. &
            (distance_discount_factor_on_child>stopping_rule_discount_factor_on_child) .OR. &
            (distance_minimum_inheritance>stopping_rule_minimum_inheritance) .OR. &
            (distance_advantage_to_owning>stopping_rule_advantage_to_owning) .OR. &
            (distance_relative_share_of_housing>stopping_rule_relative_share_of_housing) .OR. &
            (distance_relative_share_of_leisure>stopping_rule_relative_share_of_leisure) .OR. &
            (distance_convexity_of_rental_company>stopping_rule_convexity_of_rental_company) .OR. &
            (distance_housing_status_grid_expander>stopping_rule_housing_status_grid_expander) .OR. &
            (distance_largest_house_size>stopping_rule_largest_house_size) .OR. &
            (distance_probability_of_becoming_addicted>&
             stopping_rule_probability_of_becoming_addicted) .OR. &
            (distance_lambda_addiction>stopping_rule_lambda_addiction) .OR. &
            (distance_drug_market>stopping_rule_drug_market) .OR. &
            (distance_relative_share_of_addiction_1>stopping_rule_relative_share_of_addiction_1) .OR. &
            (distance_addiction_scalar>stopping_rule_addiction_scalar) .OR. &
            (distance_value_of_life>stopping_rule_value_of_life) .OR. &
            (distance_max_food_cost>stopping_rule_max_food_cost) .OR. &
            (distance_voucher_probability>stopping_rule_voucher_probability) .OR. &
            (distance_separation_rate>stopping_rule_separation_rate) .OR. &
            (distance_employment_multiplier>stopping_rule_employment_multiplier) .OR. &
            (distance_utility_cost_of_treatment>stopping_rule_utility_cost_of_treatment) .OR. &
            (distance_rent_to_price>stopping_rule_rent_to_price) .OR. &
            (distance_smallest_house_size>stopping_rule_smallest_house_size) .OR. &
            (distance_fixed_cost_to_moving>stopping_rule_fixed_cost_to_moving) .OR. &
            (distance_standard_deduction>stopping_rule_standard_deduction) .OR. &
            (distance_inheritance_amount>stopping_rule_inheritance_amount) .OR. &
            (distance_size_homelessness>stopping_rule_size_homelessness) .OR. &
            (distance_average_labor_income>stopping_rule_average_labor_income) .OR. &
            (distance_median_income>stopping_rule_median_income) .OR. &
            (distance_average_net_wealth>stopping_rule_average_net_wealth) .OR. &
            (distance_drug_threshold>stopping_rule_drug_threshold) .OR. &
            (distance_lambda_m>stopping_rule_lambda_m) .OR. &
            (distance_kappa_uem>stopping_rule_kappa_uem) .OR. &
            (distance_rho_m>stopping_rule_rho_m) .OR. &
            (distance_rho_d>stopping_rule_rho_d) .OR. &
            (distance_mu_homeless>stopping_rule_mu_homeless) .OR. &
            (distance_weight_on_child>stopping_rule_weight_on_child) .OR. &
            (distance_penalty_child_addicted>stopping_rule_penalty_child_addicted) .OR. &
            (distance_labor_income_tax_rate>stopping_rule_labor_income_tax_rate) .OR. &
            (distance_sd_permanent_productivity>stopping_rule_sd_permanent_productivity) .OR. (loop_count<1))
                        
            ! SIGMA_Y, on the share of productivity held by the bottom half.
            ! The share FALLS in sigma_y, so a model share above target means
            ! the distribution is too equal and sigma_y has to rise. The grid is
            ! rebuilt from sigma_y at the top of every loop, so the new value is
            ! in force for the solve that follows.
            if ((calibrate_sd_permanent_productivity==1) .AND. (loop_count>=1)) then

                write(*,*) "bottom half's share of productivity =",&
                    model_bottom_half_earnings_share,&
                    " target =", bottom_half_earnings_share_data
                write(*,*) "sd_permanent_productivity=", sd_permanent_productivity

                sd_permanent_productivity=max(min(sd_permanent_productivity+&
                    sd_permanent_productivity_adjuster*&
                    (model_bottom_half_earnings_share-bottom_half_earnings_share_data),&
                    3.d0),10.d0**(-2))

                distance_sd_permanent_productivity=&
                    abs(model_bottom_half_earnings_share-bottom_half_earnings_share_data)

                write(*,*) "sd_permanent_productivity=", sd_permanent_productivity,&
                    " distance_sd_permanent_productivity=", distance_sd_permanent_productivity

            end if

            ! OMEGA'S MOMENT, measured before the baseline so that every statistic
            ! the rest of this loop reads describes the baseline and not this.
            ! Switching the child term off means setting its weight to zero, which
            ! is exactly what the moment describes.
            if ((calibrate_weight_on_child==1) .AND. (include_child_in_continuation==1)&
                .AND. (loop_count>=1)) then

                child_penalty_off=1

                call solve_value_function_and_policy_functions(1)
                call converge_to_stationary_equilibrium(1)
                call stationary_equilibrium_statistics(1)

                drug_users_without_child=model_total_drug_users(1)

                child_penalty_off=0

                write(*,*) "omega counterfactual: drug users with the child penalty off =",&
                    drug_users_without_child

            end if

            call solve_value_function_and_policy_functions(1)
                            
            ! A LOADED WARM START MUST NOT BE OVERWRITTEN. The initialisation
            ! puts everyone at age one with no assets, which is the right guess
            ! only when there is no better one on disk. Once a loop has run and
            ! converged, distribution_stationary is the better guess and the
            ! flag is cleared, so this reverts to the old behaviour from the
            ! second loop of a resumed run onwards.
            if (((loop_count<3) .OR. (re_do_simulation_with_fixed_parameters==1)) .AND. &
                (have_warm_distribution==0)) then

                call initialize_feasible_distribution(1)

            end if

            have_warm_distribution=0
            
            ! THIS IS THE OPERATIVE DISTRIBUTION TOLERANCE. 2e-4, and it is
            ! already loose.
            !
            ! There used to be a second reset just above, to 1e-8, in both arms of
            ! an if whose branches were identical; it has been removed because it
            ! was dead, being overwritten here on the same pass. Both together
            ! meant the declared value never reached the iteration.
            !
            ! Worth stating plainly since it was got wrong once: there is no
            ! speed left in this number. The 655 sweeps a loop takes are what
            ! reaching 2e-4 costs, not what reaching 1e-8 would cost. Loosening
            ! it further trades directly against the moments, which are shares
            ! read to three and four decimals.
            if (include_addiction==1) then

                stopping_rule_stationary_distribution=2*10.d0**(-4)

            end if
            
            if (load_test_distribution==0) then
            
                call converge_to_stationary_equilibrium(1)
                
            else
            
                do i=1,2
    
                    write(string_used,'(i1)') i
                                   
                    open(unit=10,file="distribution_stationary"//trim(string_used)//trim(old_results)//".dat",action='read')
                        read(10,'(F30.28)') distribution_stationary(i)%vector_transition_real(1,:,:,:,:,:,:)
                    close(10)
                    
                end do
                
            end if
            
            previous_average_labor_income=model_average_labour_income(1)
            previous_median_income=median_income(1)
            previous_average_net_wealth=model_average_net_wealth(1)
            
            previous_inheritance_amount=inheritance_amount
            
            call stationary_equilibrium_statistics(1)
            call stationary_equilibirum_homeownership_rate(1)
            call govt_revenues_calc(1)
            call calculate_aggregate_consumption(1)
            call calculate_welfare(1)
            call calculate_household_housing_spending(1)
            call calculate_welfare_by_characteristics(1)
                        
            call calculate_homeownership_by_characteristics(1)            
            call stationary_equilibrium_wealth_distribution_of_old(1)
            
            if (loop_count>0) then
            
                if (include_bequests==1) then
            
                    if (inheritance_function_of_productivity==0) then
            
                        if (include_bequests_in_govt_constraint==0) then
                        
                            call calculate_updated_inheritance_amounts(1)
                                        
                        end if
                        
                        distance_inheritance_amount=maxval((1-include_bequests_in_govt_constraint)*&
                            abs(previous_inheritance_amount-inheritance_amount))
                        
                        inheritance_amount=inheritance_amount_weight*inheritance_amount+&
                            (1-inheritance_amount_weight)*previous_inheritance_amount
                            
                    else
                    
                        distance_inheritance_amount=&
                            abs(model_bequests(1)-value_of_initial_assets-model_total_inheritance(1))
                        
                        inheritance_amount=inheritance_amount+&
                             inheritance_amount_adjuster*&
                             (model_bequests(1)-value_of_initial_assets-model_total_inheritance(1))
                    
                    end if
                        
                else
                    
                    distance_inheritance_amount=0
                    
                end if
                    
            else
            
                distance_inheritance_amount=1
            
            end if
                             
            if (re_do_simulation_with_fixed_parameters==1) then
            
                distance_discount_factor=0
                distance_discount_factor_on_child=0
                distance_minimum_inheritance=0
                distance_housing_status_grid_expander=0
                distance_largest_house_size=0
                distance_probability_of_becoming_addicted=0
                distance_lambda_addiction=0
                distance_utility_cost_of_treatment=0
                distance_relative_share_of_addiction_1=0
                distance_addiction_scalar=0
                distance_value_of_life=0
                distance_max_food_cost=0
                distance_voucher_probability=0
                distance_separation_rate=0
                distance_employment_multiplier=0
                distance_rent_to_price=0
                distance_smallest_house_size=0
                distance_advantage_to_owning=0
                distance_relative_share_of_housing=0
                distance_relative_share_of_leisure=0
                distance_standard_deduction=0
                distance_convexity_of_rental_company=0
                distance_fixed_cost_to_moving=0
                distance_size_homelessness=0
                distance_lambda_m=0
                distance_kappa_uem=0
                distance_rho_m=0
                distance_rho_d=0
                        
            else
            
                if (loop_count>aftr_how_mny_lps_start_update) then
            
                    write(*,*) "discount_factor=", discount_factor
                                            
                    ! RETARGETED ONTO WEALTH OVER OUTPUT. This used to be driven
                    ! by the mortgage share of gross housing wealth against the
                    ! SCF's 0.345, and with include_ownership at zero that moment
                    ! is not merely dead, it is NOT A NUMBER: mortgages and gross
                    ! housing wealth are both identically zero, so the ratio is
                    ! 0/0. The consequence was worse than a frozen parameter.
                    ! beta + adjuster*NaN is NaN, and min(max(NaN,0),1.3) collapses
                    ! to zero under gfortran, so the discount factor was SET TO
                    ! ZERO at the end of the first calibration loop and every loop
                    ! after the first solved a completely myopic household. The
                    ! distance was NaN too, and NaN > tolerance is false, so the
                    ! convergence test read the broken parameter as converged and
                    ! said nothing.
                    !
                    ! The note has always said beta is chosen to reproduce wealth
                    ! over output in the national accounts, and the model
                    ! counterpart was already being computed and printed two lines
                    ! below the update that ignored it. That is what it targets now.
                    !
                    ! SIGN. Wealth rises with patience, so a model below target
                    ! calls for a higher beta: the update is minus the adjuster
                    ! times (model minus data), which is the same convention as
                    ! every other parameter in this loop.
                    wealth_to_output_model_1=model_total_net_wealth(1)/model_GDP_incl_imput_rent(1)

                    if (wealth_to_output_model_1 .NE. wealth_to_output_model_1) then

                        ! A MOMENT THAT IS NOT A NUMBER MUST NOT MOVE A PARAMETER
                        ! AND MUST NOT BE READ AS CONVERGED. Leave beta where it
                        ! is and force the distance large so the loop stays open
                        ! and the failure is visible.
                        write(*,*) "wealth over output is NaN: beta held at", discount_factor
                        distance_discount_factor=1

                    else

                        gap_discount_factor_1=wealth_to_output_model_1-wealth_to_output_data

                        ! The usual sign flip ratchet. Wealth over output is very
                        ! sensitive to beta close to one, so a fixed step
                        ! overshoots and then oscillates.
                        if (have_gap_discount_factor==1) then

                            if ((gap_discount_factor_1*previous_gap_discount_factor)<0) then

                                discount_factor_adjuster=&
                                    max(discount_factor_adjuster*discount_factor_damping,&
                                    discount_factor_adjuster_floor)

                            else

                                discount_factor_adjuster=&
                                    min(discount_factor_adjuster*discount_factor_growth,&
                                    discount_factor_adjuster_start)

                            end if

                        end if

                        previous_gap_discount_factor=gap_discount_factor_1
                        have_gap_discount_factor=1

                        ! BRACKET AND BISECT, for the same reason the homelessness
                        ! size does it. Wealth over output is very nearly a step
                        ! function in beta near the knife edge where beta*(1+r)
                        ! reaches one: measured here, beta of 0.957 gave 0.78 and
                        ! beta of 0.968 gave 20.79, so a twenty six fold move in
                        ! the moment across eleven thousandths of the parameter.
                        ! A proportional adjuster cannot land inside a window that
                        ! narrow, however hard it is damped; it can only straddle
                        ! it. Bisection halves the window every solve regardless
                        ! of how steep the schedule is.
                        !
                        ! Wealth over output RISES with beta, so a model below
                        ! target makes this beta the low endpoint and a model
                        ! above target makes it the high one.
                        if (wealth_to_output_model_1<wealth_to_output_data) then

                            if (discount_factor_lo<0) then

                                discount_factor_lo=discount_factor
                                discount_factor_lo_moment=wealth_to_output_model_1

                            else if ((discount_factor>discount_factor_lo) .AND. &
                                (wealth_to_output_model_1<discount_factor_lo_moment-10.d0**(-5))) then

                                ! Raised patience and wealth fell. Something else
                                ! moved under the bracket, so its endpoints are no
                                ! longer comparable.
                                write(*,*) "beta BRACKET DISCARDED: raised to ", discount_factor, &
                                    " and wealth over output fell from ", discount_factor_lo_moment, &
                                    " to ", wealth_to_output_model_1
                                discount_factor_lo=-1
                                discount_factor_hi=-1
                                discount_factor_lo_moment=-1
                                discount_factor_hi_moment=-1

                            else if (discount_factor>discount_factor_lo) then

                                discount_factor_lo=discount_factor
                                discount_factor_lo_moment=wealth_to_output_model_1

                            end if

                        else

                            if (discount_factor_hi<0) then

                                discount_factor_hi=discount_factor
                                discount_factor_hi_moment=wealth_to_output_model_1

                            else if ((discount_factor<discount_factor_hi) .AND. &
                                (wealth_to_output_model_1>discount_factor_hi_moment+10.d0**(-5))) then

                                write(*,*) "beta BRACKET DISCARDED: lowered to ", discount_factor, &
                                    " and wealth over output rose from ", discount_factor_hi_moment, &
                                    " to ", wealth_to_output_model_1
                                discount_factor_lo=-1
                                discount_factor_hi=-1
                                discount_factor_lo_moment=-1
                                discount_factor_hi_moment=-1

                            else if (discount_factor<discount_factor_hi) then

                                discount_factor_hi=discount_factor
                                discount_factor_hi_moment=wealth_to_output_model_1

                            end if

                        end if

                        distance_discount_factor=abs(gap_discount_factor_1)

                        if ((discount_factor_lo>=0) .AND. &
                            (discount_factor_hi>discount_factor_lo)) then

                            if ((discount_factor_hi-discount_factor_lo)<bracket_discount_factor_floor) then

                                ! A WINDOW THIS NARROW IS THE ANSWER. The moment
                                ! jumps across it, so no beta reproduces the target
                                ! more closely and iterating further only burns
                                ! solves. Report the two sides and stop asking.
                                write(*,*) "beta BRACKET IS AT ITS FLOOR [", discount_factor_lo, &
                                    ",", discount_factor_hi, "] with the moment jumping from ", &
                                    discount_factor_lo_moment, " to ", discount_factor_hi_moment, &
                                    " across it, against a target of ", wealth_to_output_data
                                write(*,*) "   wealth over output is a step in beta here, so this is",&
                                    " as close as the moment can be brought."
                                distance_discount_factor=0

                            else

                                discount_factor=0.5d0*(discount_factor_lo+discount_factor_hi)

                                write(*,*) "beta bisecting in [", discount_factor_lo, &
                                    ",", discount_factor_hi, "]"

                            end if

                        else

                            ! No bracket yet, so traverse.
                            discount_factor=min(max(discount_factor-discount_factor_adjuster*&
                                gap_discount_factor_1,0.5d0),1.05d0)

                        end if

                        write(*,*) "wealth_to_output_model=", wealth_to_output_model_1, &
                            " against ", wealth_to_output_data
                        write(*,*) "discount_factor_adjuster=", discount_factor_adjuster

                        ! A PINNED PARAMETER IS A RESULT, NOT A DETAIL. If beta
                        ! sits on a bound the target is not reachable by patience
                        ! alone and the number in the table would be a bound
                        ! rather than a calibration.
                        if ((discount_factor<=0.5d0+10.d0**(-8)) .OR. &
                            (discount_factor>=1.05d0-10.d0**(-8))) then

                            write(*,*) "beta IS PINNED AT A BOUND", discount_factor, &
                                " and wealth over output is ", wealth_to_output_model_1, &
                                " against ", wealth_to_output_data

                        end if

                    end if
                                         
                    write(*,*) "discount_factor=", discount_factor
                    write(*,*) "distance_discount_factor=", distance_discount_factor
                    write(*,*) "model_total_net_wealth(1)/model_GDP_incl_imput_rent(1)=", &
                        model_total_net_wealth(1)/model_GDP_incl_imput_rent(1)
                    write(*,*) "model_fraction_of_homeowners_with_mortgage(1)=", &
                        model_fraction_of_homeowners_with_mortgage(1)
                    write(*,*) "(model_mortgages(1)/model_gross_housing_wealth(1))=", &
                        (model_mortgages(1)/model_gross_housing_wealth(1))
                                            
                    write(*,*) "discount_factor_on_child=", discount_factor_on_child

                    ! A DISTANCE WHOSE PARAMETER CANNOT MOVE MUST NOT BE IN THE
                    ! CONVERGENCE TEST.
                    !
                    ! Both adjusters below are zero, so the parameter is frozen,
                    ! but the distance was still computed from a model moment and
                    ! still tested against 1e-3 in the loop condition. A frozen
                    ! parameter will not walk its moment onto its target, so the
                    ! sweep could not terminate however well everything else fit.
                    ! Guard on the adjuster, which is the same discipline the
                    ! homeownership blocks below already use.
                    if (discount_factor_on_child_adjuster==0) then

                        distance_discount_factor_on_child=0

                    else if (target_HO_of_old==1) then

                        discount_factor_on_child=min(max(discount_factor_on_child-&
                            discount_factor_on_child_adjuster*(model_homeownership_by_age_group(1,5)-&
                            homeownership_rate_of_old_data),0.005),10000.d0) 
                            
                        distance_discount_factor_on_child=&
                            abs(model_homeownership_by_age_group(1,5)-homeownership_rate_of_old_data)
                            
                        write(*,*) "model_homeownership_by_age_group=", model_homeownership_by_age_group(1,5)
                        
                    else
                    
                        discount_factor_on_child=min(max(discount_factor_on_child-&
                            discount_factor_on_child_adjuster*&
                            ((model_median_assets_to_income(1)/model_median_assets_to_income(3))-&
                            median_nw_to_income_old_to_mid_age_data),0.005),10000.d0) 
                            
                        distance_discount_factor_on_child=&
                            abs((model_median_assets_to_income(1)/model_median_assets_to_income(3))-&
                            median_nw_to_income_old_to_mid_age_data)
                    
                    end if
                            
                    write(*,*) "discount_factor_on_child=", discount_factor_on_child

                    write(*,*) "minimum_inheritance=", minimum_inheritance
                
                    minimum_inheritance=min(max(minimum_inheritance+minimum_inheritance_adjuster*&
                        (model_fraction_leaving_bequests(1)-fraction_leaving_bequests_data),0.d0),150.d0)

                    if (minimum_inheritance_adjuster==0) then

                        distance_minimum_inheritance=0

                    else

                        distance_minimum_inheritance=&
                            abs(model_fraction_leaving_bequests(1)-fraction_leaving_bequests_data)

                    end if

                    write(*,*) "minimum_inheritance=", minimum_inheritance
                    write(*,*) "model_fraction_leaving_bequests=", model_fraction_leaving_bequests(1)
                                                                 
                    if (advantage_to_owning_adjuster>0) then
                    
                        write(*,*) "advantage_to_owning=", advantage_to_owning
                    
                        advantage_to_owning=min(max(advantage_to_owning-advantage_to_owning_adjuster*&
                            (model_homeownership_rate(1)-SCF_homeownership_rate),0.d0),10000.d0) 
                                                                    
                        distance_advantage_to_owning=abs(model_homeownership_rate(1)-SCF_homeownership_rate)
                        
                        write(*,*) "advantage_to_owning=", advantage_to_owning
                        write(*,*) "distance_advantage_to_owning=", distance_advantage_to_owning
                        write(*,*) "model_homeownership_rate(1)=", model_homeownership_rate(1)
                        
                        distance_rent_to_price=0
                        
                    else
                        
                        distance_advantage_to_owning=0
                        distance_rent_to_price=0
                            
                    end if
                        
                    write(*,*) "relative_share_of_housing=", relative_share_of_housing 
                    
                    if (target_renters_rent_to_income==1) then
                                        
                        ! Raising gamma makes housing worth more against
                        ! consumption and the drug, so the household buys more of
                        ! it and the rent to income ratio RISES. A model above
                        ! target therefore calls for a smaller gamma.
                        !
                        ! THE DAMPING GOES ON THIS BRANCH, because this is the one
                        ! that runs: target_renters_rent_to_income is one. It was
                        ! first put on the else, where it compiled, printed
                        ! nothing and did nothing, and the only way to see that
                        ! was that its adjuster never appeared in the log beside
                        ! the other eight.
                        call damp_on_flip(relative_share_of_housing_adjuster,&
                            model_avg_housing_spending_renters(1)-avg_rent_to_income_data,&
                            previous_gap_relative_share_of_housing,have_gap_relative_share_of_housing,&
                            relative_share_of_housing_adjuster_start,damp_adjuster_floor)
                        write(*,*) "relative_share_of_housing_adjuster=", relative_share_of_housing_adjuster
                        relative_share_of_housing=&
                            min(max(relative_share_of_housing-relative_share_of_housing_adjuster*&
                            (model_avg_housing_spending_renters(1)-avg_rent_to_income_data),0.01),0.9) 
                                                                     
                        distance_relative_share_of_housing=&
                            abs(model_avg_housing_spending_renters(1)-avg_rent_to_income_data)
                                    
                        write(*,*) "model_avg_housing_spending_all=", model_avg_housing_spending_renters(1)
                            
                    else
                    
                        relative_share_of_housing=&
                            min(max(relative_share_of_housing-relative_share_of_housing_adjuster*&
                            (mass_of_renters_at_housing_spending(1,1)-SW_renters_spend_over_X_on_hous_2),0.01),0.9) 
                                                                     
                        distance_relative_share_of_housing=&
                            abs(mass_of_renters_at_housing_spending(1,1)-SW_renters_spend_over_X_on_hous_2)
                                    
                        write(*,*) "mass_of_renters_at_housing_spending(1,1)=", mass_of_renters_at_housing_spending(1,1)
                    
                    end if
                                                 
                    write(*,*) "relative_share_of_housing=", relative_share_of_housing 
                    write(*,*) "distance_relative_share_of_housing=", distance_relative_share_of_housing
                                        
                    write(*,*) "relative_share_of_housing=", relative_share_of_housing 
                                    
                    ! MULTIPLICATIVE, BECAUSE THE PARAMETER AND ITS MOMENT ARE NOT ON
                    ! THE SAME SCALE. The moment is a share of hours, bounded in
                    ! [0,1], so the gap can never exceed 0.4 in magnitude, while
                    ! the weight sits around 6.5. An additive step of
                    ! adjuster times gap is therefore at most 0.2 on a parameter
                    ! of 6.5, about three per cent a loop, and it does not care
                    ! how far away the moment is.
                    !
                    ! Measured: 6.786, 6.598, 6.411, falling 0.19 a loop while
                    ! labour supply sat at 0.025 against a target of 0.4. Not
                    ! stuck, and not a corner either — only two per cent of
                    ! households choose zero hours, so there is no grid to blame.
                    ! Just a rule that would need about thirty more loops, six
                    ! hours of wall clock, to cover ground a proportional step
                    ! covers in four.
                    !
                    ! Normalising the gap by the target makes the step
                    ! proportional to the parameter, which is what a scale-free
                    ! weight calls for, and the damping keeps it from ringing once
                    ! it arrives. Direction is unchanged: a model below target
                    ! still lowers the weight.
                    call damp_on_flip(relative_share_of_leisure_adjuster,&
                        model_labor_supply(1)/model_total_hours(1)-avg_labor_supply_data,&
                        previous_gap_relative_share_of_leisure,have_gap_relative_share_of_leisure,&
                        relative_share_of_leisure_adjuster_start,damp_adjuster_floor)
                    write(*,*) "relative_share_of_leisure_adjuster=", relative_share_of_leisure_adjuster
                    relative_share_of_leisure=&
                        min(max(relative_share_of_leisure*&
                        (1+relative_share_of_leisure_adjuster*&
                        (model_labor_supply(1)/model_total_hours(1)-avg_labor_supply_data)/&
                        max(avg_labor_supply_data,10.d0**(-12))),0.01),1000.d0) 
                                                                 
                    distance_relative_share_of_leisure=&
                        abs(model_labor_supply(1)/model_total_hours(1)-avg_labor_supply_data)
                                
                    write(*,*) "model_labor_supply(1)/model_total_hours(1)=", &
                        model_labor_supply(1)/model_total_hours(1)

                    ! LABELLED WITH THE PARAMETER THEY ACTUALLY CARRY. These two
                    ! printed the LEISURE weight under the HOUSING label and then
                    ! repeated the housing distance, so the log showed
                    ! relative_share_of_housing taking two different values a line
                    ! apart, one of them 7.85 against a parameter bounded at 0.9.
                    ! It also corrupts export_moments.py, which takes the last
                    ! printed value for a label, so the housing weight in the
                    ! paper would have been the leisure weight.
                    write(*,*) "relative_share_of_leisure=", relative_share_of_leisure
                    write(*,*) "distance_relative_share_of_leisure=", distance_relative_share_of_leisure
                                             
                    write(*,*) "housing_status_grid_expander=", housing_status_grid_expander
                        
                    if (calibrate_size_of_smallest_house_hhld_can_buy==1) then

                        ! RETARGETED ONTO THE SIZE DISTRIBUTION. This used to be
                        ! bracketed on the homeownership rate against the SCF's
                        ! 0.659, which is a dead moment now: include_homeownership
                        ! is zero, so model_homeownership_rate is identically zero
                        ! and the update drove the expander with a constant gap of
                        ! -0.659 every iteration. The expander sets the curvature
                        ! of the grid between the smallest and largest sizes, so
                        ! the share in the LARGEST size is what it actually
                        ! identifies.
                        !
                        ! THE LARGEST SIZE CARRIES THIS MOMENT, not the expander.
                        ! Three shares have two free numbers in them, so two size
                        ! parameters identify them and a third would be chasing the
                        ! same target: h0 takes the smallest share, h2 the largest,
                        ! and the middle follows. The expander is SET at its
                        ! starting curvature. It was tried on this moment first and
                        ! it cannot reach it, because what empties the largest unit
                        ! is the LEVEL of h2 rather than the curvature between h0
                        ! and h2: raising the expander from 1.8 to 2.17 moved the
                        ! largest share from 6 per cent to zero rather than towards
                        ! 62.7.
                        gap_house_size_1=&
                            model_housing_size_dist(1,housing_status_grid_size-1)-&
                            housing_size_dist_data(2)

                        if (have_gap_largest_house_size==1) then

                            if ((gap_house_size_1*previous_gap_largest_house_size)<0) then

                                largest_house_size_adjuster=&
                                    max(largest_house_size_adjuster*house_size_adjuster_damping,&
                                    house_size_adjuster_floor)

                            else

                                largest_house_size_adjuster=&
                                    min(largest_house_size_adjuster*house_size_adjuster_growth,&
                                    largest_house_size_adjuster_start)

                            end if

                        end if

                        previous_gap_largest_house_size=gap_house_size_1
                        have_gap_largest_house_size=1

                        write(*,*) "largest_house_size_adjuster=", largest_house_size_adjuster

                        largest_house_size=&
                            min(max(largest_house_size+largest_house_size_adjuster*&
                            gap_house_size_1,0.02d0),1.d0)

                        distance_largest_house_size=&
                            abs(model_housing_size_dist(1,housing_status_grid_size-1)-&
                            housing_size_dist_data(2))

                        write(*,*) "largest_house_size=", largest_house_size
                        write(*,*) "distance_largest_house_size=", distance_largest_house_size

                        distance_housing_status_grid_expander=0
                            
                        distance_rent_to_price=0
                                                
                    else
                    
                        distance_housing_status_grid_expander=0
                        distance_rent_to_price=0
                        
                    end if
                    
                    if ((calibrate_size_of_smallest_house_hhld_can_buy==0) .AND. &
                        (advantage_to_owning_adjuster==0)) then
                        
                        write(*,*) "rent(1)/housing_price=", rent(1,:)/housing_price(1)
                        
                        distance_rent_to_price=(1-fix_rent)*abs(model_homeownership_rate(1)-SCF_homeownership_rate)
                            
                        if (fix_rent==0) then
                            rent(1,:)=rent(1,:)-rent_to_price_adjuster*&
                                (model_homeownership_rate(1)-SCF_homeownership_rate)
                        end if
                        
                        write(*,*) "rent(1)/housing_price=", rent(1,:)/housing_price(1)
                        write(*,*) "distance_rent_to_price=", distance_advantage_to_owning
                        write(*,*) "model_homeownership_rate(1)=", model_homeownership_rate(1)
                        
                    else
                    
                        write(*,*) "rent(1)=", rent(1,:)
                    
                        if (fix_rent==0) then
                            rent(1,:)=rent(1,:)-rent_to_price_adjuster*&
                                (rent(1,:)/housing_price(1)-rent_to_housing_price)
                        end if
                            
                        write(*,*) "rent(1)=", rent(1,:)
                            
                    end if
                    
                    write(*,*) "size_of_smallest_house_hhld_can_buy=", size_of_smallest_house_hhld_can_buy
                    write(*,*) "housing_status_grid_expander=", housing_status_grid_expander
                    write(*,*) "housing_size(index_of_smallest_house_hhld_can_buy)=", &
                        housing_size(index_of_smallest_house_hhld_can_buy)
                    write(*,*) "model_fraction_of_homeowners_with_mortgage(1)=", model_fraction_of_homeowners_with_mortgage(1)
                    
                    if ((mortgage_deductibility>0) .OR. (property_tax_deductibility>0)) then
                    
                        write(*,*) "govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1)=", &
                            100*(govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1))
                            
                    end if
                    
                    write(*,*) "smallest_rental_relative_to_lowest_income=", smallest_rental_relative_to_lowest_income                    
                    
                    if (calibrate_smallest_house_size==1) then

                        ! TARGETED ON THE SIZE DISTRIBUTION, not on a housing cost
                        ! share. See housing_size_dist_data for why.
                        write(*,*) "model_housing_size_dist=", model_housing_size_dist(1,:)
                        write(*,*) "housing_size_dist_data=", housing_size_dist_data
                        write(*,*) "smallest_rental_relative_to_lowest_income=", &
                            smallest_rental_relative_to_lowest_income

                        gap_house_size_1=&
                            model_housing_size_dist(1,0)-housing_size_dist_data(0)

                        if (have_gap_smallest_house_size==1) then

                            if ((gap_house_size_1*previous_gap_smallest_house_size)<0) then

                                smallest_house_size_adjuster=&
                                    max(smallest_house_size_adjuster*house_size_adjuster_damping,&
                                    house_size_adjuster_floor)

                            else

                                smallest_house_size_adjuster=&
                                    min(smallest_house_size_adjuster*house_size_adjuster_growth,&
                                    smallest_house_size_adjuster_start)

                            end if

                        end if

                        previous_gap_smallest_house_size=gap_house_size_1
                        have_gap_smallest_house_size=1

                        write(*,*) "smallest_house_size_adjuster=", smallest_house_size_adjuster

                        smallest_rental_relative_to_lowest_income=&
                            min(max(smallest_rental_relative_to_lowest_income-smallest_house_size_adjuster*&
                            gap_house_size_1,0.d0),10.d0) 
                                                                     
                        distance_smallest_house_size=abs(model_housing_size_dist(1,0)-&
                            housing_size_dist_data(0))
                                                         
                    else
                    
                        distance_smallest_house_size=0
                    
                    end if
                    
                    write(*,*) "smallest_rental_relative_to_lowest_income=", smallest_rental_relative_to_lowest_income
                    write(*,*) "mass_of_renters_at_housing_spending=", &
                        mass_of_renters_at_housing_spending(1,target_30_perc*1+(1-target_30_perc)*2)
                        
                    write(*,*) "labor_income_tax_rate=", labor_income_tax_rate

                    ! THE PLUS IS CORRECT AND THE NAME IS NOT. labor_income_tax_rate
                    ! is the RETENTION SCALE in the tax function
                    !
                    !     tax = y - labor_income_tax_rate * y**curvature
                    !
                    ! so it multiplies income KEPT, not income taken. Raising it
                    ! lowers the average effective tax rate, which is why an
                    ! average tax above target is met by raising this number. Its
                    ! declared value of 0.75 only makes sense read that way; as a
                    ! marginal rate it would be absurd. Anyone auditing signs from
                    ! the variable names will read this one as inverted and be
                    ! wrong, which is why the note is here rather than nowhere.
                    call damp_on_flip(labor_income_tax_rate_adjuster,&
                        model_average_labour_income_tax(1)-average_labor_income_tax_data,&
                        previous_gap_labor_income_tax_rate,have_gap_labor_income_tax_rate,&
                        labor_income_tax_rate_adjuster_start,damp_adjuster_floor)
                    write(*,*) "labor_income_tax_rate_adjuster=", labor_income_tax_rate_adjuster
                    labor_income_tax_rate=max(min(labor_income_tax_rate+labor_income_tax_rate_adjuster*&
                        (model_average_labour_income_tax(1)-average_labor_income_tax_data),2.d0),0.d0)

                    distance_labor_income_tax_rate=&
                        abs(model_average_labour_income_tax(1)-average_labor_income_tax_data)

                    write(*,*) "average labour income tax rate =", model_average_labour_income_tax(1),&
                        " against ", average_labor_income_tax_data,&
                        " distance_labor_income_tax_rate=", distance_labor_income_tax_rate

                    if ((labor_income_tax_rate<=10.d0**(-8)) .OR. (labor_income_tax_rate>=2.d0-10.d0**(-8))) then

                        write(*,*) "the retention scale IS PINNED AT A BOUND", labor_income_tax_rate,&
                            " and the average labour income tax rate is ", model_average_labour_income_tax(1),&
                            " against ", average_labor_income_tax_data

                    end if
                        
                    write(*,*) "labor_income_tax_rate=", labor_income_tax_rate
                                                            
                    if (mortgage_deductibility==1) then
                    
                        write(*,*) "fraction_using_MID(1)=", fraction_using_MID(1)
                        write(*,*) "standard_deduction_as_percent_of_average_labor_income=", &
                            standard_deduction_as_percent_of_average_labor_income
                    
                        standard_deduction_as_percent_of_average_labor_income=&
                            max(min(standard_deduction_as_percent_of_average_labor_income+&
                            standard_deduction_adjuster*&
                            (100*(govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1))-&
                            MID_to_GDP_data),1.d0),0.d0)
                            
                        distance_standard_deduction=&
                            abs(100*(govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1)))
                            
                        write(*,*) "standard_deduction_as_percent_of_average_labor_income=", &
                            standard_deduction_as_percent_of_average_labor_income
                        write(*,*) "distance_standard_deduction=", distance_standard_deduction
                    
                    else
                        
                        distance_standard_deduction=0
                        standard_deduction_as_percent_of_average_labor_income=0 !0.08
                    
                    end if
                                        
                    if (fixed_cost_to_moving_adjuster>0)  then
                    
                        write(*,*) "fixed_cost_to_moving=", fixed_cost_to_moving
                                
!                        fixed_cost_to_moving=max(min(fixed_cost_to_moving-fixed_cost_to_moving_adjuster*&
!                            (model_years_in_same_rental(1,2)-average_years_in_same_rental_data),1.d0),0.d0)
!                            
!                        distance_fixed_cost_to_moving=abs(model_years_in_same_rental(1,2)-average_years_in_same_rental_data)
                            
                        write(*,*) "fixed_cost_to_moving=", fixed_cost_to_moving
                        write(*,*) "distance_fixed_cost_to_moving=", distance_fixed_cost_to_moving
                    
                    else
                    
                        distance_fixed_cost_to_moving=0
                    
                    end if
                                        
                    ! LAMBDA on the substance use disorder rate.
                    write(*,*) "model_fraction_addicted(1)=", model_fraction_addicted(1)
                    write(*,*) "sud_rate_data=", sud_rate_data
                    write(*,*) "probability_of_becoming_addicted_if_experiment=", &
                        probability_of_becoming_addicted_if_experiment

                    if (smooth_addiction_hazard==1) then

                        ! LAMBDA IS BRACKETED THROUGH THE ONSET AT THE MEAN
                        ! QUANTITY, not directly, and that is what makes the
                        ! bracket transferable.
                        !
                        ! lambda is a hazard per unit of drug, so its scale is
                        ! whatever the model's consumption units happen to be and
                        ! an adjuster tuned at one calibration would be wrong at
                        ! the next. The onset a mean user faces,
                        ! 1-exp(-lambda vbar), is a probability whatever the
                        ! units, it is monotone in lambda, and it is the same
                        ! object the flat hazard was: so the update runs on it
                        ! with the step and the bracket the flat hazard already
                        ! used, and lambda is recovered by inverting at the
                        ! model's own mean. Nothing is left to depend on a guess
                        ! about scale except the very first backward pass.
                        !
                        ! Sign is unchanged: a higher hazard means more of the
                        ! people who use acquire the disorder, so prevalence
                        ! rises in it and the update subtracts the gap.
                        mean_drug_quantity_1=model_drugs_used_by_users_on_average(1)

                        if (mean_drug_quantity_1>0) then

                            onset_at_mean_1=1-exp(-lambda_addiction*mean_drug_quantity_1)

                            ! SECANT ON THE ONSET, NOT A FIXED STEP, and the
                            ! first step comes from the flow balance rather than
                            ! from the adjuster.
                            !
                            ! An equilibrium is hours, so the number of loops IS
                            ! the calibration time and a fixed step that has to
                            ! creep is the wrong instrument. Two things fix it.
                            !
                            ! THE FIRST STEP IS ANALYTIC. In the stationary
                            ! distribution the disorder is a two state flow
                            ! balance: onset times the mass using equals recovery
                            ! times the mass carrying it, so prevalence is very
                            ! nearly proportional to the onset at a given share
                            ! who use. Scaling the onset by the ratio of target
                            ! to model prevalence therefore lands close on the
                            ! first try, where the fixed step would have taken
                            ! twenty loops to cover the same ground when the
                            ! model came in at nine times the data.
                            !
                            ! AFTER THAT IT IS A SECANT. Two (onset, prevalence)
                            ! pairs give the local slope, which is what the
                            ! proportionality above only approximates once the
                            ! share who use responds to the hazard as well. The
                            ! step is clipped to a factor of four either way so a
                            ! flat or noisy secant cannot throw lambda across the
                            ! bracket, and it falls back to the proportional rule
                            ! whenever the two prevalences are too close to
                            ! divide by.
                            ! AND THE SECANT IS ONLY READ WHEN ITS SLOPE HAS THE SIGN THE
                            ! MODEL GUARANTEES. Prevalence rises in the onset hazard with
                            ! everything else held fixed, so a measured slope that is
                            ! negative is not news about the model, it is a reading taken
                            ! through another instrument's move. This loop is Gauss-Seidel:
                            ! b moved in the same pass, and when it moves participation by
                            ! more than the hazard moves conversion the difference in
                            ! prevalence carries b's sign, not lambda's.
                            !
                            ! WHAT WAS ACTUALLY MEASURED ON THE RUN THIS GUARD WAS ADDED
                            ! FOR, since the first reading of it was wrong and the wrong
                            ! reading is the more tempting one. Prevalence fell from 5.79e-4
                            ! to 7.31e-6 while b cut participation thirteenfold in the same
                            ! loop, and it looked as though the secant had inverted. It had
                            ! not. onset_at_mean is recomputed each loop at the MODEL'S OWN
                            ! mean quantity, and that mean collapsed from 1.09e-2 to 1.19e-3
                            ! along with participation, so the onset fell from 1.19e-3 to
                            ! 1.30e-4 even though lambda QUADRUPLED, from 0.1095 to 0.4381,
                            ! which is its clamp. The slope came out at +1.86, the secant
                            ! was not rejected, and it asked for an onset of 0.0685 that the
                            ! clamp cut to four times the current one. Lambda was pushing as
                            ! hard as it is allowed to, in the right direction, the whole
                            ! time.
                            !
                            ! So the collapse was b's alone, and b's damping is what fixes
                            ! it. The lesson lambda carries is a different one: a hazard
                            ! clipped to a factor of four a loop cannot hold prevalence
                            ! while another instrument moves the population it acts on by a
                            ! factor of thirteen. Damping b is what makes lambda's clamp
                            ! sufficient.
                            !
                            ! The slope test stays, because a contaminated slope CAN come
                            ! out negative and there is nothing to be gained from stepping
                            ! on it. It is a safeguard against a case that can arise and not
                            ! a fix for one that did. A rejected secant falls back to the
                            ! proportional rule, which cannot point the wrong way: it scales
                            ! the hazard by target over model and both are positive.
                            !
                            ! WORTH KNOWING WHEN READING THE SECANT AT ALL: because the two
                            ! onsets are measured at two different mean quantities, the
                            ! slope is not a clean derivative of prevalence in the hazard.
                            ! It mixes in the change in how much users buy. That is a
                            ! consequence of calibrating the onset at the mean rather than
                            ! calibrating lambda directly, which is deliberate and is
                            ! explained above, but it means the secant is an approximation
                            ! and should be read as one.
                            lambda_secant_slope_1=0

                            if (abs(model_fraction_addicted(1)-previous_sud_rate)>10.d0**(-12)) then

                                lambda_secant_slope_1=(onset_at_mean_1-previous_onset_at_mean)/&
                                    (model_fraction_addicted(1)-previous_sud_rate)

                            end if

                            if ((have_lambda_secant==1) .AND. &
                                (abs(model_fraction_addicted(1)-previous_sud_rate)>10.d0**(-6)) .AND. &
                                (abs(onset_at_mean_1-previous_onset_at_mean)>10.d0**(-12)) .AND. &
                                (lambda_secant_slope_1>0)) then

                                onset_step_1=onset_at_mean_1-&
                                    (model_fraction_addicted(1)-sud_rate_data)*&
                                    lambda_secant_slope_1

                            elseif (model_fraction_addicted(1)>10.d0**(-8)) then

                                if ((have_lambda_secant==1) .AND. (lambda_secant_slope_1<=0) .AND. &
                                    (abs(model_fraction_addicted(1)-previous_sud_rate)>10.d0**(-6))) then

                                    write(*,*) "lambda secant REJECTED, slope=", lambda_secant_slope_1, &
                                        ": prevalence moved against the hazard, so another instrument",&
                                        " moved more than this one. Falling back to the proportional rule."

                                end if

                                onset_step_1=onset_at_mean_1*&
                                    (sud_rate_data/model_fraction_addicted(1))

                            else

                                onset_step_1=onset_at_mean_1-&
                                    lambda_addiction_adjuster*&
                                    (model_fraction_addicted(1)-sud_rate_data)

                            end if

                            gap_lambda_addiction_1=model_fraction_addicted(1)-sud_rate_data

                            if (have_gap_lambda_addiction==1) then

                                if ((gap_lambda_addiction_1*previous_gap_lambda_addiction)<0) then

                                    lambda_clamp=max(1+(lambda_clamp-1)*0.5d0,lambda_clamp_floor)

                                else

                                    lambda_clamp=min(1+(lambda_clamp-1)*1.2d0,lambda_clamp_start)

                                end if

                            end if

                            previous_gap_lambda_addiction=gap_lambda_addiction_1
                            have_gap_lambda_addiction=1

                            write(*,*) "lambda_clamp=", lambda_clamp

                            onset_step_1=max(min(onset_step_1,lambda_clamp*onset_at_mean_1),&
                                onset_at_mean_1/lambda_clamp)

                            previous_onset_at_mean=onset_at_mean_1
                            previous_sud_rate=model_fraction_addicted(1)
                            have_lambda_secant=1

                            onset_at_mean_1=max(min(onset_step_1,0.2d0),1.d0*10.d0**(-5))

                            lambda_addiction=-log(1-onset_at_mean_1)/mean_drug_quantity_1

                            write(*,*) "model_drugs_used_by_users_on_average(1)=", mean_drug_quantity_1
                            write(*,*) "onset_at_the_mean_quantity=", onset_at_mean_1

                        else

                            write(*,*) "no drug use at all, lambda left where it is"

                        end if

                        distance_lambda_addiction=&
                            abs(model_fraction_addicted(1)-sud_rate_data)

                        ! The flat hazard is not calibrated alongside it. Two
                        ! parameters on one moment is not identification, it is a
                        ! race, and with the smooth form on the flat number is
                        ! read only where the household abstains, where it is
                        ! multiplied by zero.
                        distance_probability_of_becoming_addicted=0

                        write(*,*) "lambda_addiction=", lambda_addiction
                        write(*,*) "distance_lambda_addiction=", distance_lambda_addiction

                    else

                        probability_of_becoming_addicted_if_experiment=&
                            max(min(probability_of_becoming_addicted_if_experiment-&
                            probability_of_becoming_addicted_adjuster*&
                            (model_fraction_addicted(1)-sud_rate_data),0.2d0),1.d0*10.d0**(-5))

                        distance_probability_of_becoming_addicted=&
                            abs(model_fraction_addicted(1)-sud_rate_data)

                        distance_lambda_addiction=0

                        write(*,*) "probability_of_becoming_addicted_if_experiment=", &
                            probability_of_becoming_addicted_if_experiment
                        write(*,*) "distance_probability_of_becoming_addicted=", &
                            distance_probability_of_becoming_addicted

                    end if

                    ! THE UTILITY COST OF TREATMENT, on take up given a SUD.
                    !
                    ! Sign: a higher cost means fewer households take treatment,
                    ! so take up FALLS in it and the update adds the gap. Same
                    ! secant as lambda and rent, for the same reason: the number
                    ! of loops is the calibration time.
                    !
                    ! Take up is bounded in [0,1] and the cost is in utils, so
                    ! the fallback step is a fixed one on the gap rather than a
                    ! proportional rule, which would be meaningless at a take up
                    ! of zero.
                    if (include_treatment==1) then

                        write(*,*) "model_treatment_take_up(1)=", model_treatment_take_up(1)
                        write(*,*) "treatment_take_up_data=", treatment_take_up_data
                        write(*,*) "utility_cost_of_treatment=", utility_cost_of_treatment

                        ! THE SIGN. Take up FALLS in the cost: the cost is
                        ! subtracted from flow utility in the period treatment is
                        ! taken, so raising it makes treatment less attractive.
                        ! The step therefore has to move the cost AGAINST the
                        ! gap, not with it. Written with a plus, as it was, a
                        ! take up below target raised the cost, which lowered take
                        ! up further, which raised the cost again: measured over
                        ! thirteen iterations the cost ratcheted from 0.020 to
                        ! 0.151 in exact steps of adjuster*(0.24-0) = 0.012 while
                        ! take up sat at zero throughout. The secant below cannot
                        ! rescue it, because a take up that never moves fails the
                        ! guard on its own change and the fallback runs every
                        ! time. This is the same error as the kappa_uem update,
                        ! which was also copied from a moment that runs the other
                        ! way.
                        treatment_step_1=utility_cost_of_treatment-&
                            utility_cost_of_treatment_adjuster*&
                            (treatment_take_up_data-model_treatment_take_up(1))

                        if ((have_treatment_secant==1) .AND. &
                            (abs(model_treatment_take_up(1)-previous_treatment_take_up)>10.d0**(-6)) .AND. &
                            (abs(utility_cost_of_treatment-previous_utility_cost_of_treatment)>10.d0**(-10))) then

                            treatment_step_1=utility_cost_of_treatment-&
                                (model_treatment_take_up(1)-treatment_take_up_data)*&
                                (utility_cost_of_treatment-previous_utility_cost_of_treatment)/&
                                (model_treatment_take_up(1)-previous_treatment_take_up)

                        end if

                        previous_utility_cost_of_treatment=utility_cost_of_treatment
                        previous_treatment_take_up=model_treatment_take_up(1)
                        have_treatment_secant=1

                        utility_cost_of_treatment=max(min(treatment_step_1,10.d0),0.d0)

                        distance_utility_cost_of_treatment=&
                            abs(model_treatment_take_up(1)-treatment_take_up_data)

                        write(*,*) "utility_cost_of_treatment=", utility_cost_of_treatment
                        write(*,*) "distance_utility_cost_of_treatment=", &
                            distance_utility_cost_of_treatment

                        ! SAY SO WHEN THE COST CAN GO NO LOWER, the way the
                        ! lambda_m floor does. At a cost of zero treatment is free
                        ! in utils and still costs the household its drug
                        ! spending, since taking it forces abstention. So a take
                        ! up of zero here is not a failure of this update: it says
                        ! the benefit side is too small, which is g, mu_H, pi_r
                        ! and the abstention itself, and no value of bar_tau^u
                        ! reaches the target.
                        if ((utility_cost_of_treatment<=0.d0) .AND. &
                            (model_treatment_take_up(1)<treatment_take_up_data)) then

                            write(*,*) "utility_cost_of_treatment IS AT ITS FLOOR 0 and take up is ",&
                                model_treatment_take_up(1), " against a target of ", treatment_take_up_data
                            write(*,*) "   treatment is declined even when free, so the target is out of",&
                                " reach on the benefit side, not on the cost."

                        end if

                    ! MU_H, on the model's own increase in recovery from housing.
                    ! The ratio FALLS in mu_H, since mu_H is how good recovery on
                    ! the street is, so the step moves mu_H with the gap: a model
                    ! ratio above target means the street is too bad and mu_H rises.
                    if ((model_recovery_homeless(1)>0) .AND. (model_recovery_housed(1)>0)) then

                        write(*,*) "model recovery housed, homeless =",&
                            model_recovery_housed(1), model_recovery_homeless(1)
                        write(*,*) "model recovery ratio =",&
                            model_recovery_housed(1)/model_recovery_homeless(1),&
                            " target =", milby_recovery_ratio_data
                        write(*,*) "mu_homeless=", mu_homeless

                        mu_homeless=max(min(mu_homeless+mu_homeless_adjuster*&
                            (model_recovery_housed(1)/model_recovery_homeless(1)-&
                            milby_recovery_ratio_data),1.d0),10.d0**(-3))

                        distance_mu_homeless=&
                            abs(model_recovery_housed(1)/model_recovery_homeless(1)-&
                            milby_recovery_ratio_data)

                        write(*,*) "mu_homeless=", mu_homeless,&
                            " distance_mu_homeless=", distance_mu_homeless

                    else

                        ! No homeless household carries the disorder, so the
                        ! gradient has no denominator. Say so rather than dividing.
                        write(*,*) "mu_homeless HELD: no homeless household carries the disorder, so",&
                            " the recovery gradient cannot be measured this iteration"

                    end if

                    ! OMEGA, on how much drug use rises when the child term is off.
                    ! Use rises in the gap, and a LARGER omega means the parent
                    ! already internalises more, so switching the term off changes
                    ! more and the measured gap RISES in omega. A model gap above
                    ! target therefore calls for a smaller omega.
                    ! THE BASELINE HAS TO EXIST FOR THE GAP TO BE A GAP. With a
                    ! baseline using mass of 2.3e-4 the ratio came back as 325
                    ! against a target of 0.18 and omega went to zero in one step,
                    ! which is a statement about the denominator rather than about
                    ! how much a parent internalises. A tenth of the participation
                    ! rate the model is trying to reproduce is the floor.
                    if ((calibrate_weight_on_child==1) .AND. (drug_users_without_child>0)&
                        .AND. (model_total_drug_users(1)>&
                        10.d0**(-1)*participation_rate_data)) then

                        write(*,*) "drug users, baseline and child term off =",&
                            model_total_drug_users(1), drug_users_without_child

                        child_use_gap_1=drug_users_without_child/model_total_drug_users(1)-1

                        write(*,*) "model child use gap =",&
                            child_use_gap_1, " target =", child_use_gap_data
                        write(*,*) "weight_on_child=", weight_on_child

                        ! The step is taken on a clamped gap for the same reason
                        ! theta's is: the sign is informative long before the
                        ! magnitude is.
                        weight_on_child=max(min(weight_on_child-weight_on_child_adjuster*&
                            max(min(child_use_gap_1-child_use_gap_data,1.d0),-1.d0),&
                            1.d0),0.d0)

                        distance_weight_on_child=abs(child_use_gap_1-child_use_gap_data)

                        write(*,*) "weight_on_child=", weight_on_child,&
                            " distance_weight_on_child=", distance_weight_on_child

                    else if (calibrate_weight_on_child==1) then

                        write(*,*) "omega HELD: baseline users ", model_total_drug_users(1),&
                            " and users with the child term off ", drug_users_without_child,&
                            ": one of the two is too small for the gap to mean anything"
                        distance_weight_on_child=1

                    end if

                    ! DELTA_D, on the ratio of child disorder rates.
                    if (calibrate_penalty_child_addicted==1) then

                        child_sud_num_1=0
                        child_sud_den_1=0

                        do child_node_index_1=1,employment_grid_size

                            child_sud_num_1=child_sud_num_1+&
                                newborn_employment_probability(child_node_index_1,1,1)*&
                                percent_addicted_by_employment(1,child_node_index_1)

                            child_sud_den_1=child_sud_den_1+&
                                newborn_employment_probability(child_node_index_1,0,1)*&
                                percent_addicted_by_employment(1,child_node_index_1)

                        end do

                        if (child_sud_den_1>10.d0**(-10)) then

                            child_sud_ratio_model_1=child_sud_num_1/child_sud_den_1

                            gap_penalty_child_1=child_sud_ratio_model_1-child_sud_ratio_data

                            if (have_gap_penalty_child==1) then

                                if ((gap_penalty_child_1*previous_gap_penalty_child)<0) then

                                    penalty_child_addicted_adjuster=&
                                        max(penalty_child_addicted_adjuster*penalty_child_adjuster_damping,&
                                        penalty_child_adjuster_floor)

                                else

                                    penalty_child_addicted_adjuster=&
                                        min(penalty_child_addicted_adjuster*penalty_child_adjuster_growth,&
                                        penalty_child_adjuster_start)

                                end if

                            end if

                            previous_gap_penalty_child=gap_penalty_child_1
                            have_gap_penalty_child=1

                            write(*,*) "child SUD ratio model =", child_sud_ratio_model_1,&
                                " target =", child_sud_ratio_data
                            write(*,*) "penalty_child_addicted=", penalty_child_addicted

                            penalty_child_addicted=&
                                max(min(penalty_child_addicted-penalty_child_addicted_adjuster*&
                                gap_penalty_child_1,0.9d0),0.d0)

                            distance_penalty_child_addicted=abs(gap_penalty_child_1)

                            write(*,*) "penalty_child_addicted=", penalty_child_addicted,&
                                " distance_penalty_child_addicted=", distance_penalty_child_addicted

                            ! The newborn draw is built from this penalty, so it
                            ! has to be rebuilt now rather than at the next setup,
                            ! which never runs again.
                            call create_newborn_employment_probability()

                            if ((penalty_child_addicted<=10.d0**(-8)) .OR. &
                                (penalty_child_addicted>=0.9d0-10.d0**(-8))) then

                                write(*,*) "delta_d IS PINNED AT A BOUND", penalty_child_addicted,&
                                    " and the child SUD ratio is ", child_sud_ratio_model_1,&
                                    " against ", child_sud_ratio_data

                            end if

                        else

                            write(*,*) "child SUD ratio has an empty denominator: delta_d held at",&
                                penalty_child_addicted
                            distance_penalty_child_addicted=1

                        end if

                    else

                        distance_penalty_child_addicted=0

                    end if


                    else

                        distance_utility_cost_of_treatment=0

                    end if

                    ! THE ELEVEN, FREED AND BRACKETED.
                    !
                    ! Each on the moment its row in the note's internal table
                    ! names. Signs are stated rather than left to be inferred,
                    ! because a wrong sign here shows up as a moment walking
                    ! away rather than as an error.
                    !
                    ! theta, the weight on drugs, on drug spending over income
                    ! averaged across users, light and heavy together, which is
                    ! the population the moment below is taken over. More weight,
                    ! more spending, so the update
                    ! adds the gap the other way round: subtract model minus
                    ! data.
                    ! THE MOMENT IS A WEIGHTED AVERAGE OVER BOTH KINDS OF USER.
                    !
                    ! It used to be the ratio for the experimenters alone, who are
                    ! the users WITHOUT a disorder, since the code keeps the two
                    ! groups disjoint. So a target meant for users as a whole was
                    ! being asked of the lighter half of them.
                    !
                    ! Now each group's own drug to income ratio is formed first and
                    ! the two are averaged with their shares of the using
                    ! population as weights, which is the object the data number is.
                    ! A GROUP WITH NO INCOME HAS NO RATIO.
                    !
                    ! Households carrying the disorder are largely out of work with
                    ! no assets, so their measured income can be numerically zero
                    ! while they still spend on the drug out of the consumption
                    ! floor. Dividing one by the other gave a group ratio of
                    ! 1,815,832 on the first iteration, which then swamped the
                    ! weighted average. The 1e-12 guard stopped a crash and
                    ! produced a meaningless number instead, which is worse.
                    !
                    ! So a group ratio is only formed when that group's income is a
                    ! real quantity, taken as a thousandth of average labour income
                    ! times its mass. When it is not, the pooled ratio over both
                    ! groups is used for that iteration, which is well behaved
                    ! because the denominator is dominated by the group that does
                    ! earn, and the log says so rather than passing it off as the
                    ! weighted average.
                    ! A TENTH OF AVERAGE INCOME PER HOUSEHOLD, not a thousandth.
                    ! At a thousandth the guard passed on a group whose income per
                    ! head was still near zero, and the ratio it then formed was
                    ! 1,815,823. A group whose average income is below a tenth of
                    ! the mean has no meaningful drug to income ratio, whatever the
                    ! numerator is.
                    income_floor_1=10.d0**(-1)*model_average_labour_income(1)

                    ! EACH ACCUMULATOR IS ALREADY A RATIO. It is divided by its
                    ! group's total income where the distribution is summed, and
                    ! dividing it again here is what produced 62 and 1,204,097 for
                    ! a share the budget constraint caps at one. A negative value
                    ! is the sentinel for a group with no income at all.
                    drug_share_experimenters_1=&
                        model_experimenters_total_drug_spending_to_total_income(1)
                    drug_share_addicted_1=&
                        model_addicted_total_addiction_spending_to_total_income(1)

                    ! A GROUP COUNTS ONLY IF ITS RATIO MEANS SOMETHING, and a group
                    ! that fails is dropped from the average rather than replaced
                    ! by a pooled ratio. Pooling put the failing group back in
                    ! through the numerator.
                    use_experimenters_1=(model_mass_experimenters(1)>0) .AND. &
                        (drug_share_experimenters_1>=0) .AND. &
                        (model_experimenters_total_income(1)>&
                        income_floor_1*model_mass_experimenters(1))
                    use_addicts_1=(model_mass_addicts(1)>0) .AND. &
                        (drug_share_addicted_1>=0) .AND. &
                        (model_addicted_total_income(1)>&
                        income_floor_1*model_mass_addicts(1))

                    if (use_experimenters_1 .AND. use_addicts_1) then

                        drug_share_weighted_1=&
                            (model_mass_experimenters(1)*drug_share_experimenters_1+&
                            model_mass_addicts(1)*drug_share_addicted_1)/&
                            (model_mass_experimenters(1)+model_mass_addicts(1))

                    else if (use_experimenters_1) then

                        drug_share_weighted_1=drug_share_experimenters_1
                        write(*,*) "drug share: the group with a disorder has no income to speak of,",&
                            " so the moment is the experimenters alone this iteration"

                    else if (use_addicts_1) then

                        drug_share_weighted_1=drug_share_addicted_1
                        write(*,*) "drug share: the experimenters have no income to speak of,",&
                            " so the moment is the group with a disorder alone this iteration"

                    else

                        drug_share_weighted_1=-1

                    end if

                    write(*,*) "drug share, experimenters and with a SUD =",&
                        drug_share_experimenters_1, drug_share_addicted_1
                    write(*,*) "drug share, weighted by their population shares =",&
                        drug_share_weighted_1, " target =", drug_spending_share_data

                    if (drug_share_weighted_1>=0) then

                        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1

                        ! A TRUST REGION ON THE GAP AND ON THE STEP. The share
                        ! cannot exceed one, so a gap above one is a measurement
                        ! failure rather than a signal about theta, and the raw gap
                        ! of 109 moved theta from 0.44 to its floor in one step
                        ! while the next iteration undid it. Clamping the gap keeps
                        ! the sign and drops the magnitude; halving or doubling per
                        ! iteration is still fast and cannot land on a bound.
                        drug_share_gap_1=max(min(drug_share_weighted_1-&
                            drug_spending_share_data,1.d0),-1.d0)

                        relative_share_of_addiction_1=&
                            max(min(relative_share_of_addiction_1-&
                            relative_share_of_addiction_adj*drug_share_gap_1,&
                            min(0.9d0,2*relative_share_of_addiction_1)),&
                            max(10.d0**(-4),relative_share_of_addiction_1/2))

                        distance_relative_share_of_addiction_1=&
                            abs(drug_share_weighted_1-drug_spending_share_data)

                        write(*,*) "relative_share_of_addiction_1=", relative_share_of_addiction_1
                        write(*,*) "distance_relative_share_of_addiction_1=",&
                            distance_relative_share_of_addiction_1

                    else

                        write(*,*) "drug share HELD: neither using group has income worth dividing by,",&
                            " so theta is not moved on a moment that does not exist"
                        distance_relative_share_of_addiction_1=1

                    end if

                    ! b, the Stone-Geary endowment, on participation. A LARGER b
                    ! deters use, since the marginal value of the first unit is
                    ! theta/b, so participation FALLS in b and the update adds
                    ! the gap. Multiplicative, because b is of order 1e-8 and an
                    ! additive step in it is meaningless.
                    write(*,*) "addiction_scalar_1=", addiction_scalar_1
                    ! NO GUARD ON PARTICIPATION BEING POSITIVE. Zero participation
                    ! is exactly the state b has to move out of, and the gap is
                    ! normalised by the target so it cannot be worse than minus
                    ! one however empty the model is. Skipping the update there
                    ! left the model parked at the corner it needed to leave.
                    gap_addiction_scalar_1=model_exprimenters(1)-participation_rate_data

                    if (have_gap_addiction_scalar==1) then

                        if ((gap_addiction_scalar_1*previous_gap_addiction_scalar)<0) then

                            addiction_scalar_adjuster=max(addiction_scalar_adjuster*&
                                addiction_scalar_damping,addiction_scalar_floor)

                        else

                            addiction_scalar_adjuster=min(addiction_scalar_adjuster*&
                                addiction_scalar_growth,addiction_scalar_adjuster_start)

                        end if

                    end if

                    previous_gap_addiction_scalar=gap_addiction_scalar_1
                    have_gap_addiction_scalar=1

                    addiction_scalar_1=max(min(addiction_scalar_1*&
                        (1+addiction_scalar_adjuster*&
                        gap_addiction_scalar_1/&
                        max(participation_rate_data,10.d0**(-12))),&
                        10*addiction_scalar_1),addiction_scalar_1/10)
                    distance_addiction_scalar=abs(gap_addiction_scalar_1)
                    write(*,*) "addiction_scalar_adjuster=", addiction_scalar_adjuster
                    write(*,*) "addiction_scalar_1=", addiction_scalar_1
                    write(*,*) "distance_addiction_scalar=", distance_addiction_scalar

                    ! aleph, on the model implied value of a statistical life.
                    ! A larger aleph makes life worth more, so the VSL rises in
                    ! it and the update subtracts the gap.
                    ! THE MOMENT IS SCALE FREE, so the comparison is too. The
                    ! model's value of life is a sum of V/MU_c and carries the
                    ! numeraire with it; dividing by average labour income turns
                    ! it into the multiple the data number is quoted as, and
                    ! nothing in the block then depends on what a unit of the
                    ! model is worth.
                    if (model_average_labour_income(1)>0) then

                        model_vsl_ratio_1=model_value_of_life(1)/&
                            model_average_labour_income(1)

                        write(*,*) "model_value_of_life(1)=", model_value_of_life(1),&
                            " over average labour income =", model_vsl_ratio_1,&
                            " target =", vsl_data

                        ! A TRUST REGION. The adjuster is ten and the gap is measured
                        ! in the same units as the parameter, so an early gap of 88
                        ! moves it by 885 and any starting value below that lands on a
                        ! clamp. Halving or one and a half times per iteration is
                        ! still fast and cannot overshoot into a bound.
                        gap_value_of_life_1=model_vsl_ratio_1-vsl_data

                        if (have_gap_value_of_life==1) then

                            if ((gap_value_of_life_1*previous_gap_value_of_life)<0) then

                                value_of_life_trust=max(value_of_life_trust*&
                                    value_of_life_trust_damping,value_of_life_trust_floor)

                            else

                                value_of_life_trust=min(value_of_life_trust*&
                                    value_of_life_trust_growth,value_of_life_trust_start)

                            end if

                        end if

                        previous_gap_value_of_life=gap_value_of_life_1
                        have_gap_value_of_life=1

                        write(*,*) "value_of_life_trust=", value_of_life_trust

                        value_of_life_step_1=value_of_life-value_of_life_adjuster*&
                            gap_value_of_life_1
                        value_of_life_step_1=max(min(value_of_life_step_1,&
                            (1+value_of_life_trust)*value_of_life),&
                            value_of_life/(1+value_of_life_trust))
                        value_of_life=max(min(value_of_life_step_1,10.d0**(4)),10.d0**(-2))
                        distance_value_of_life=abs(model_vsl_ratio_1-vsl_data)

                    else

                        write(*,*) "aleph HELD: average labour income is zero, so the",&
                            " value of life has no multiple to be quoted as"
                        distance_value_of_life=1

                    end if
                    write(*,*) "value_of_life=", value_of_life
                    write(*,*) "distance_value_of_life=", distance_value_of_life

                    ! cbar, the food stamp floor, on food stamps over labour
                    ! income. A higher floor pays more out, so the share rises
                    ! in it and the update subtracts the gap.
                    if (model_average_labour_income(1)>0) then
                        write(*,*) "max_food_cost=", max_food_cost
                        max_food_cost=max(min(max_food_cost-max_food_cost_adjuster*&
                            (govt_spending_on_food_stamps(1)/model_average_labour_income(1)-&
                            food_stamps_share_data),1.d0),10.d0**(-4))
                        distance_max_food_cost=&
                            abs(govt_spending_on_food_stamps(1)/model_average_labour_income(1)-food_stamps_share_data)
                        write(*,*) "max_food_cost=", max_food_cost
                        write(*,*) "distance_max_food_cost=", distance_max_food_cost
                    end if

                    ! pi_V, the voucher lottery, on recipients over the income
                    ! eligible. Coverage rises in it, so subtract the gap.
                    write(*,*) "probability_of_voucher_benchmark_used=", probability_of_voucher_benchmark_used
                    call damp_on_flip(voucher_probability_adjuster,&
                        model_eligibles_getting_voucher(1)-voucher_coverage_data,&
                        previous_gap_voucher_probability,have_gap_voucher_probability,&
                        voucher_probability_adjuster_start,damp_adjuster_floor)
                    write(*,*) "voucher_probability_adjuster=", voucher_probability_adjuster
                    probability_of_voucher_benchmark_used=&
                        max(min(probability_of_voucher_benchmark_used-voucher_probability_adjuster*&
                        (model_eligibles_getting_voucher(1)-voucher_coverage_data),1.d0),10.d0**(-5))
                    distance_voucher_probability=&
                        abs(model_eligibles_getting_voucher(1)-voucher_coverage_data)
                    write(*,*) "probability_of_voucher_benchmark_used=", probability_of_voucher_benchmark_used
                    write(*,*) "distance_voucher_probability=", distance_voucher_probability

                    ! bar pi^eu, the separation rate, on the unemployment rate.
                    ! Unemployment rises in it, so subtract the gap.
                    write(*,*) "probability_becoming_unemployed=", probability_becoming_unemployed
                    call damp_on_flip(separation_rate_adjuster,&
                        model_fraction_unemployed(1)-unemployment_rate_data,&
                        previous_gap_separation_rate,have_gap_separation_rate,&
                        separation_rate_adjuster_start,damp_adjuster_floor)
                    write(*,*) "separation_rate_adjuster=", separation_rate_adjuster
                    probability_becoming_unemployed=&
                        max(min(probability_becoming_unemployed-separation_rate_adjuster*&
                        (model_fraction_unemployed(1)-unemployment_rate_data),1.d0),10.d0**(-6))
                    distance_separation_rate=abs(model_fraction_unemployed(1)-unemployment_rate_data)
                    write(*,*) "probability_becoming_unemployed=", probability_becoming_unemployed
                    write(*,*) "distance_separation_rate=", distance_separation_rate

                    ! kappa_ued, the employment multiplier for the SUD, on the
                    ! unemployment rate GIVEN a SUD. It multiplies the
                    ! separation rate and divides the job finding rate, so
                    ! unemployment among those with the disorder rises in it.
                    write(*,*) "multiple_of_probabilities_of_employment_if_addicted=", &
                        multiple_of_probabilities_of_employment_if_addicted
                    call damp_on_flip(employment_multiplier_adjuster,&
                        model_fraction_addicted_and_unemployed(1)-unemployment_rate_sud_data,&
                        previous_gap_employment_multiplier,have_gap_employment_multiplier,&
                        employment_multiplier_adjuster_start,damp_adjuster_floor)
                    write(*,*) "employment_multiplier_adjuster=", employment_multiplier_adjuster
                    multiple_of_probabilities_of_employment_if_addicted=&
                        max(min(multiple_of_probabilities_of_employment_if_addicted-&
                        employment_multiplier_adjuster*&
                        (model_fraction_addicted_and_unemployed(1)-unemployment_rate_sud_data),&
                        20.d0),1.d0)
                    distance_employment_multiplier=&
                        abs(model_fraction_addicted_and_unemployed(1)-unemployment_rate_sud_data)
                    write(*,*) "multiple_of_probabilities_of_employment_if_addicted=", &
                        multiple_of_probabilities_of_employment_if_addicted
                    write(*,*) "distance_employment_multiplier=", distance_employment_multiplier

                    ! ================================================
                    ! THE SMI BLOCK AND THE TWO WAGE PENALTIES.
                    !
                    ! Each is guarded on its own adjuster, so a parameter that is
                    ! frozen contributes a zero distance rather than a moment the
                    ! sweep can never satisfy. That failure mode cost a whole
                    ! calibration once: a distance computed from a live moment
                    ! while its parameter could not move means the loop cannot
                    ! terminate however well everything else fits.
                    !
                    ! Signs, stated because a wrong one shows up as a moment
                    ! walking away rather than as an error:
                    !   lambda_m up   -> SMI less persistent -> SMI share of the
                    !                    homeless DOWN
                    !   kappa_uem up  -> employment margins worse -> employment
                    !                    rate given SMI DOWN, so the update ADDS,
                    !                    unlike kappa_ued above whose moment is an
                    !                    unemployment rate and whose update
                    !                    subtracts
                    !   rho_m up      -> smaller penalty -> homeless income UP
                    !   rho_d up      -> smaller penalty -> employed homeless can
                    !                    afford housing -> employed share of the
                    !                    homeless DOWN

                    if ((lambda_m_adjuster>0) .AND. (number_of_smi_states>1)) then

                        ! THE FLOOR IS THE PROFILE'S, NOT 0.001. Below
                        ! lambda_m_floor the onset identity has no non negative
                        ! solution, the SMI state empties, and every SMI moment
                        ! reads zero, so the loop cannot recover: the moment stops
                        ! responding to the parameter and the update keeps pushing
                        ! the same way. Stopping at the floor keeps the model
                        ! interpretable and makes the tension visible instead.
                        lambda_m=min(max(lambda_m+lambda_m_adjuster*&
                            (model_smi_share_of_homeless(1)-smi_share_of_homeless_data),&
                            lambda_m_floor),0.5d0)

                        if (lambda_m<=lambda_m_floor+10.d0**(-9)) then

                            write(*,*) "lambda_m IS AT ITS FLOOR", lambda_m_floor, &
                                " and the SMI share of the homeless is", &
                                model_smi_share_of_homeless(1), " against a target of", &
                                smi_share_of_homeless_data
                            write(*,*) "   the profile cannot deliver this moment: the prevalence path, the onset"
                            write(*,*) "   identity and this target are not mutually consistent."

                        end if

                        distance_lambda_m=&
                            abs(model_smi_share_of_homeless(1)-smi_share_of_homeless_data)

                        write(*,*) "lambda_m=", lambda_m, " distance_lambda_m=", distance_lambda_m

                    else

                        distance_lambda_m=0

                    end if

                    if ((kappa_uem_adjuster>0) .AND. (number_of_smi_states>1)) then

                        ! THE SIGN HERE IS THE OPPOSITE OF ITS NEIGHBOUR'S, and
                        ! that is not a slip. kappa_ued above is moved against an
                        ! UNEMPLOYMENT rate, which rises in the parameter, so its
                        ! update subtracts. kappa_uem is moved against an
                        ! EMPLOYMENT rate, which falls in the parameter, so its
                        ! update must ADD. The block was written by analogy with
                        ! the SUD block and inherited the minus, which drove
                        ! kappa_uem to its floor of one, removed the SMI
                        ! employment effect altogether, and left a distance that
                        ! could never fall below its stopping rule, so the loop
                        ! could not terminate however well anything else fitted.
                        kappa_uem=min(max(kappa_uem+kappa_uem_adjuster*&
                            (model_employment_rate_given_smi(1)-employment_rate_given_smi_data),&
                            1.0d0),20.d0)

                        distance_kappa_uem=&
                            abs(model_employment_rate_given_smi(1)-employment_rate_given_smi_data)

                        write(*,*) "kappa_uem=", kappa_uem, " distance_kappa_uem=", distance_kappa_uem

                    else

                        distance_kappa_uem=0

                    end if

                    if ((rho_m_adjuster>0) .AND. (number_of_smi_states>1) .AND. &
                        (include_wage_penalties==1)) then

                        rho_m=min(max(rho_m-rho_m_adjuster*&
                            (model_homeless_income_share(1)-homeless_income_share_data),&
                            0.05d0),1.d0)

                        distance_rho_m=&
                            abs(model_homeless_income_share(1)-homeless_income_share_data)

                        write(*,*) "rho_m=", rho_m, " distance_rho_m=", distance_rho_m

                    else

                        distance_rho_m=0

                    end if

                    if ((rho_d_adjuster>0) .AND. (include_wage_penalties==1)) then

                        rho_d=min(max(rho_d+rho_d_adjuster*&
                            (model_employed_share_of_homeless(1)-employed_share_of_homeless_data),&
                            0.05d0),1.d0)

                        distance_rho_d=&
                            abs(model_employed_share_of_homeless(1)-employed_share_of_homeless_data)

                        write(*,*) "rho_d=", rho_d, " distance_rho_d=", distance_rho_d

                    else

                        distance_rho_d=0

                    end if

                    write(*,*) "model_fraction_homeless(1)=", model_fraction_homeless(1)
                    write(*,*) "size_homelessness=", size_homelessness

                    ! A bracket whose endpoints were priced under different values
                    ! of life is not a bracket. Test for that before using it.
                    if ((size_homelessness_lo>=0) .OR. (size_homelessness_hi>=0)) then

                        if ((value_of_life_at_bracket>0) .AND. &
                            (abs(value_of_life-value_of_life_at_bracket)>&
                            bracket_value_of_life_tolerance*value_of_life_at_bracket)) then

                            write(*,*) "size_homelessness BRACKET DISCARDED: the value of life moved from ",&
                                value_of_life_at_bracket, " to ", value_of_life,&
                                " so its endpoints are not comparable"
                            size_homelessness_lo=-1
                            size_homelessness_hi=-1
                            size_homelessness_lo_moment=-1
                            size_homelessness_hi_moment=-1
                            value_of_life_at_bracket=-1

                        end if

                    end if

                    if ((size_homelessness_lo<0) .AND. (size_homelessness_hi<0)) then

                        value_of_life_at_bracket=value_of_life

                    end if

                    ! Tighten the bracket with what this evaluation just proved,
                    ! unless it proves the bracket itself is stale.
                    if (model_fraction_homeless(1)<fraction_homeless_data) then

                        if (size_homelessness_lo<0) then

                            size_homelessness_lo=size_homelessness
                            size_homelessness_lo_moment=model_fraction_homeless(1)

                        else if ((size_homelessness>size_homelessness_lo) .AND. &
                            (model_fraction_homeless(1)<size_homelessness_lo_moment-10.d0**(-5))) then

                            ! Raised the parameter and homelessness fell.
                            write(*,*) "size_homelessness BRACKET DISCARDED: raised to ",&
                                size_homelessness, " and homelessness fell from ",&
                                size_homelessness_lo_moment, " to ", model_fraction_homeless(1)
                            size_homelessness_lo=-1
                            size_homelessness_hi=-1
                            size_homelessness_lo_moment=-1
                            size_homelessness_hi_moment=-1

                        else if (size_homelessness>size_homelessness_lo) then

                            size_homelessness_lo=size_homelessness
                            size_homelessness_lo_moment=model_fraction_homeless(1)

                        end if

                    else

                        if (size_homelessness_hi<0) then

                            size_homelessness_hi=size_homelessness
                            size_homelessness_hi_moment=model_fraction_homeless(1)

                        else if ((size_homelessness<size_homelessness_hi) .AND. &
                            (model_fraction_homeless(1)>size_homelessness_hi_moment+10.d0**(-5))) then

                            ! Lowered the parameter and homelessness rose.
                            write(*,*) "size_homelessness BRACKET DISCARDED: lowered to ",&
                                size_homelessness, " and homelessness rose from ",&
                                size_homelessness_hi_moment, " to ", model_fraction_homeless(1)
                            size_homelessness_lo=-1
                            size_homelessness_hi=-1
                            size_homelessness_lo_moment=-1
                            size_homelessness_hi_moment=-1

                        else if (size_homelessness<size_homelessness_hi) then

                            size_homelessness_hi=size_homelessness
                            size_homelessness_hi_moment=model_fraction_homeless(1)

                        end if

                    end if

                    if ((size_homelessness_lo>=0) .AND. &
                        (size_homelessness_hi>size_homelessness_lo)) then

                        ! Bisect. This halves the window every equilibrium solve,
                        ! so a window of 0.08 is down to the stopping rule in about
                        ! seven of them however wide the initial bracket was.
                        size_homelessness=&
                            0.5d0*(size_homelessness_lo+size_homelessness_hi)

                        write(*,*) "size_homelessness bisecting in [",&
                            size_homelessness_lo, ",", size_homelessness_hi, "]"

                    else

                        ! No bracket yet, so traverse, which is what the adjuster
                        ! is good at.
                        gap_size_homelessness_1=model_fraction_homeless(1)-fraction_homeless_data

                        if (have_gap_size_homelessness==1) then

                            if ((gap_size_homelessness_1*previous_gap_size_homelessness)<0) then

                                size_homelessness_adjuster=max(size_homelessness_adjuster*&
                                    size_homelessness_damping,size_homelessness_adjuster_floor)

                            else

                                size_homelessness_adjuster=min(size_homelessness_adjuster*&
                                    size_homelessness_growth,size_homelessness_adjuster_start)

                            end if

                        end if

                        previous_gap_size_homelessness=gap_size_homelessness_1
                        have_gap_size_homelessness=1

                        write(*,*) "size_homelessness_adjuster=", size_homelessness_adjuster

                        size_homelessness=max(min(size_homelessness-size_homelessness_adjuster*&
                            gap_size_homelessness_1,1.d0),0.d0)

                        ! Say so if the traverse has run out of room. At a street
                        ! worth as much as housing_size(0) and free, a model still
                        ! below target is not a failure of this update: nothing in
                        ! the housing ladder makes homelessness attractive, so the
                        ! rental grid or the food floor is what has to move.
                        if ((size_homelessness>=1.d0) .AND. &
                            (model_fraction_homeless(1)<fraction_homeless_data)) then

                            write(*,*) "size_homelessness IS AT ITS CEILING 1 and homelessness is ",&
                                model_fraction_homeless(1), " against a target of ", fraction_homeless_data
                            write(*,*) "   no bracket exists below the ceiling: the street cannot be",&
                                " made attractive enough through this parameter."

                        end if

                    end if

                    distance_size_homelessness=&
                        abs(model_fraction_homeless(1)-fraction_homeless_data)

                    write(*,*) "size_homelessness=", size_homelessness
                                 
                end if
                                        
            end if
                                                                                     
            distance_rental_market(1)=maxval(abs(total_rental_demand(1,:)-total_rental_supply(1,:)))

            ! THE DRUG MARKET.
            !
            ! V is the quantity households actually bought, accumulated over the
            ! distribution in model_drugs_consumed_by_users. The supply price at
            ! that quantity is nu_1 V^(nu_2-1).
            !
            ! In the benchmark nu_1 is whatever puts that price at one, which is
            ! the note's normalisation, so the market clears every loop and the
            ! price never moves. In a counterfactual nu_1 is the benchmark's, so
            ! the price is whatever the supply curve says and the loop iterates
            ! until the price households faced and the price the quantity
            ! implies agree.
            call clear_drug_market(1)

            write(*,*) "rent(1)=", rent(1,:)
            write(*,*) "rental_supply(1)=", total_rental_supply(1,:)
            write(*,*) "rental_demand(1)=", total_rental_demand(1,:)
            write(*,*) "distance_rental_market(1)=", distance_rental_market(1)
                                                                   
            write(*,*) "one market"

            rental_market_adjuster=1
            
            if (re_do_simulation_with_fixed_parameters==5) then
        
                distance_rental_market(1)=maxval((abs(himmelberg_etal_rent_to_price-(rent(1,:)/housing_price(1)))))
                    
                if (fix_rent==0) then
                    rent(1,:)=rent(1,:)+rental_market_adjuster*(himmelberg_etal_rent_to_price-&
                        (rent(1,:)/housing_price(1)))
                end if
                    
            else
            
                rental_market_adjuster=10.d0**(-3)
                            
                distance_rental_market(1)=maxval(abs(total_rental_demand(1,:)-total_rental_supply(1,:)))
                                      
            end if
                                               
            write(*,*) "rent(1)=", rent(1,:)
            write(*,*) "rental_market_adjuster=", rental_market_adjuster
            write(*,*) "model_mortgages(1)/model_gross_housing_wealth(1)=", model_mortgages(1)/model_gross_housing_wealth(1)
            write(*,*) "model_average_rental_unit_size(1)=", model_average_rental_unit_size(1)
            write(*,*) "model_average_owner_occupied_unit_size(1)=", model_average_owner_occupied_unit_size(1)
            write(*,*) "model_average_rental_unit_size(1)/model_average_owner_occupied_unit_size(1)=", &
                model_average_rental_unit_size(1)/model_average_owner_occupied_unit_size(1)
!            write(*,*) "model_fraction_of_homeowners_with_mortgage(1)=", model_fraction_of_homeowners_with_mortgage(1)
                
            if (mortgage_deductibility>0) then
            
                write(*,*) "% govt spending on mortgage interest deductions(1)/model_GDP_incl_imput_rent(1)=", &
                    100*(govt_spending_on_mortgage_interest_deductions(1)/model_GDP_incl_imput_rent(1))
                
            end if
                
            write(*,*) "model_homeownership_rate(1)=", model_homeownership_rate(1)
                                                        
            call cpu_time(simulation_stop_time)
            
            write(*,*) "re_do_simulation_with_fixed_parameters=", re_do_simulation_with_fixed_parameters
            write(*,*) "relative_share_of_housing=", relative_share_of_housing
            write(*,*) "relative_share_of_leisure=", relative_share_of_leisure
            
            if (calibrate_size_of_smallest_house_hhld_can_buy==0) then
            
                write(*,*) "advantage_to_owning=", advantage_to_owning
                
            end if
            
            write(*,*) "discount_factor=", discount_factor
            write(*,*) "discount_factor_on_child=", discount_factor_on_child
                        
            write(*,*) "convexity_of_rental_company=", convexity_of_rental_company(:)
                                    
            write(*,*) "housing_status_grid_expander=", housing_status_grid_expander
                                    
            mass_at_top_financial=0
            
            do i=1,2
                                    
                mass_at_top_financial=mass_at_top_financial+&
                    sum(distribution_stationary(i)%vector_transition_real(1,:,financial_grid_size,:,:,:,:)) 
                    
            end do
                        
            write(*,*) "labor_income_tax_rate=", labor_income_tax_rate
            write(*,*) "utility_improvement,", utility_improvement
            write(*,*) "rental_management_costs=", rental_management_costs(:)
            write(*,*) "smallest_house_size=", smallest_house_size
            write(*,*) "index_of_smallest_house_hhld_can_buy=", index_of_smallest_house_hhld_can_buy
            write(*,*) "housing_size(index_of_smallest_house_hhld_can_buy)=", &
                housing_size(index_of_smallest_house_hhld_can_buy)
            write(*,*) "size_homelessness=", size_homelessness
            write(*,*) "largest_financial_chosen_in_equilibrium=", largest_financial_chosen_in_equilibrium
            write(*,*) "largest_housing_size_consumed_in_equilibrium=", largest_housing_size_consumed_in_equilibrium
            write(*,*) "smallest_financial_chosen_in_equilibrium=", smallest_financial_chosen_in_equilibrium
            write(*,*) "financial_grid(smallest_financial_chosen_in_equilibrium)=", &
                financial_grid(smallest_financial_chosen_in_equilibrium)
